INSERT OR REPLACE INTO blogs (id, related_document_id, title, content, author, category, tags, thumbnail, status, views, created_at, updated_at) VALUES (
  'blog_7b107b85',
  'doc_5ebe13fc',
  'ETC Full Exam Guide by ShikshaSahayak',
  'replace(''<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>GTU ETC Full Marks Guide | ShikshaSahayak</title>\n</head>\n<body style="margin:0;background:#050814;">\n<!-- BLOGGER POST HTML VIEW: ShikshaSahayak dark theme version. Paste directly in Blogger HTML view. -->\n\n<style>\n  .pp-wrap,.pp-etc-wrap{--bg:#050814;--panel:#0f1726;--panel2:#121c2e;--ink:#f5f7fb;--muted:#a8b0c2;--line:#263449;--orange:#ff6b18;--orange2:#ff8a2a;--blue:#5aa7ff;--cyan:#28d6c6;--green:#39d98a;--purple:#8c6cff;--pink:#ff5d8f;--yellow:#ffd166;--red:#ff6b6b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;background:radial-gradient(circle at 10% -10%,rgba(255,107,24,.22),transparent 28%),radial-gradient(circle at 92% 0%,rgba(90,167,255,.18),transparent 31%),linear-gradient(180deg,#050814 0%,#070b18 45%,#050814 100%)!important;color:var(--ink)!important;line-height:1.68;max-width:1180px!important;margin:0 auto!important;padding:18px!important;border-radius:24px!important;box-sizing:border-box!important;overflow:hidden!important}.pp-wrap *,.pp-etc-wrap *{box-sizing:border-box}.pp-wrap a,.pp-etc-wrap a{color:inherit;text-decoration:none;pointer-events:auto;position:relative;z-index:3}.pp-dark-topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid rgba(255,255,255,.14);background:rgba(10,16,31,.82);box-shadow:0 24px 70px rgba(0,0,0,.35);border-radius:22px;padding:16px 20px;margin-bottom:24px;backdrop-filter:blur(10px)}.pp-dark-logo{font-size:26px;font-weight:950;letter-spacing:-.05em}.pp-dark-logo span:first-child{color:#fff}.pp-dark-logo span:last-child{color:var(--orange)}.pp-dark-nav{display:flex;gap:22px;align-items:center;color:#cbd3e3;font-weight:800;font-size:14px;flex-wrap:wrap}.pp-dark-nav span{opacity:.9}.pp-wrap .hero,.pp-etc-wrap .pp-etc-hero{position:relative;border:1px solid rgba(255,255,255,.10)!important;background:linear-gradient(135deg,rgba(18,28,46,.97),rgba(11,16,30,.94))!important;border-radius:30px!important;padding:44px 34px!important;margin:0 0 28px!important;overflow:hidden!important;box-shadow:0 26px 70px rgba(0,0,0,.30)!important}.pp-wrap .hero:before,.pp-etc-wrap .pp-etc-hero:before{content:"";position:absolute;right:-90px;top:-90px;width:280px;height:280px;background:radial-gradient(circle,rgba(255,107,24,.40),transparent 62%);border-radius:50%}.pp-wrap .hero:after,.pp-etc-wrap .pp-etc-hero:after{content:"";position:absolute;left:-120px;bottom:-120px;width:280px;height:280px;background:radial-gradient(circle,rgba(90,167,255,.24),transparent 60%);border-radius:50%}.pp-wrap .hero-content,.pp-etc-wrap .pp-etc-hero>*{position:relative;z-index:1}.pp-wrap .eyebrow,.pp-etc-wrap .pp-eyebrow{display:inline-flex!important;align-items:center;gap:8px;background:rgba(255,107,24,.14)!important;color:#ffb280!important;border:1px solid rgba(255,107,24,.35)!important;padding:8px 13px!important;border-radius:999px!important;font-weight:950!important;font-size:13px!important;letter-spacing:.16em!important;text-transform:uppercase!important}.pp-wrap h1,.pp-etc-wrap .pp-etc-hero h1{font-size:clamp(32px,5.4vw,66px)!important;line-height:1.02!important;letter-spacing:-.055em!important;font-weight:950!important;color:#fff!important;margin:16px 0 12px!important}.pp-wrap h1 span,.pp-etc-wrap .pp-etc-hero h1 span{color:var(--orange)!important}.pp-wrap .subtitle,.pp-etc-wrap .pp-etc-hero p{max-width:850px!important;color:#c4ccdb!important;font-size:18px!important;margin:16px 0 0!important}.pp-wrap .author-card,.pp-etc-wrap .pp-author-mini{position:relative;display:inline-grid!important;gap:3px;background:rgba(255,255,255,.06)!important;border:1px solid rgba(255,255,255,.12)!important;border-radius:18px!important;padding:14px 18px!important;margin-top:22px!important;color:#fff!important;box-shadow:none!important}.pp-wrap .author-name,.pp-etc