INSERT OR REPLACE INTO blogs (id, related_document_id, title, content, author, category, tags, thumbnail, status, views, created_at, updated_at) VALUES (
  'blog_473490a3',
  'doc_a9e50fb4',
  'Physics full mark guide by ShikshaSahayak',
  'replace(''<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>GTU BE Physics Full Marks Guide | ShikshaSahayak</title>\n</head>\n<body style="margin:0;background:#050917;">\n\n<style>\n:root{\n  --pp-bg:#050917;\n  --pp-panel:#0f172a;\n  --pp-card:#111c31;\n  --pp-card2:#0b1324;\n  --pp-border:#24344f;\n  --pp-text:#f8fafc;\n  --pp-muted:#a8b3c8;\n  --pp-orange:#ff7a1a;\n  --pp-orange2:#ff9a3d;\n  --pp-blue:#58a6ff;\n  --pp-green:#2dd4bf;\n  --pp-purple:#a78bfa;\n  --pp-pink:#fb7185;\n  --pp-yellow:#facc15;\n}\n.padhaku-blog-wrap{\n  background:\n    radial-gradient(circle at top left, rgba(255,122,26,.16), transparent 34%),\n    radial-gradient(circle at top right, rgba(88,166,255,.14), transparent 30%),\n    linear-gradient(180deg,#050917 0%,#070b18 48%,#050917 100%);\n  color:var(--pp-text);\n  font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;\n  line-height:1.75;\n  padding:28px 16px;\n  border-radius:22px;\n}\n.padhaku-blog-wrap *{box-sizing:border-box}\n.pp-container{max-width:1120px;margin:0 auto}\n.pp-hero{\n  border:1px solid var(--pp-border);\n  background:\n    linear-gradient(135deg, rgba(17,28,49,.96), rgba(8,13,27,.98)),\n    radial-gradient(circle at 90% 20%, rgba(255,122,26,.18), transparent 28%);\n  border-radius:28px;\n  padding:34px;\n  box-shadow:0 24px 70px rgba(0,0,0,.38);\n  position:relative;\n  overflow:hidden;\n}\n.pp-hero:before{content:"";position:absolute;inset:-80px -80px auto auto;width:260px;height:260px;background:rgba(255,122,26,.16);border-radius:50%}\n.pp-brand{display:inline-flex;align-items:center;font-weight:900;font-size:28px;letter-spacing:-.8px;margin-bottom:18px}\n.pp-brand span:first-child{color:#fff}.pp-brand span:last-child{color:var(--pp-orange)}\n.pp-kicker{display:inline-flex;gap:8px;align-items:center;color:var(--pp-orange);font-weight:800;letter-spacing:.18em;text-transform:uppercase;font-size:12px}\n.pp-title{font-size:clamp(32px,5vw,58px);line-height:1.05;margin:12px 0 12px;letter-spacing:-1.5px}.pp-title strong{color:var(--pp-orange)}\n.pp-subtitle{color:var(--pp-muted);font-size:18px;max-width:820px}\n.pp-module-chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}.pp-chip{border:1px solid var(--pp-border);background:#172238;color:#dbeafe;padding:8px 12px;border-radius:999px;font-size:13px;font-weight:700}\n.pp-author-mini{margin:24px 0 0;max-width:430px;border:1px solid rgba(255,122,26,.45);background:linear-gradient(135deg,rgba(255,122,26,.13),rgba(15,23,42,.88));border-radius:18px;padding:16px 18px}.pp-author-mini .label{color:var(--pp-muted);font-size:13px}.pp-author-mini .name{font-size:28px;font-weight:900;color:#fff;line-height:1.15}.pp-author-mini .role{color:var(--pp-orange);font-weight:800}.pp-author-mini .edu{color:#b6c2d6;font-size:13px;margin-top:4px}\n.pp-section{margin-top:30px;border:1px solid var(--pp-border);background:linear-gradient(180deg,rgba(17,28,49,.94),rgba(9,15,28,.96));border-radius:24px;padding:26px;box-shadow:0 18px 50px rgba(0,0,0,.25)}\n.pp-section-title{margin:0 0 16px;font-size:clamp(24px,3vw,36px);line-height:1.15;letter-spacing:-.7px}.pp-section-title .accent{color:var(--pp-orange)}\n.pp-note{border-left:4px solid var(--pp-orange);background:rgba(255,122,26,.10);padding:14px 16px;border-radius:14px;color:#f8fafc;margin:16px 0}.pp-note.blue{border-left-color:var(--pp-blue);background:rgba(88,166,255,.10)}.pp-note.green{border-left-color:var(--pp-green);background:rgba(45,212,191,.10)}.pp-note.pink{border-left-color:var(--pp-pink);background:rgba(251,113,133,.10)}\n.pp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.pp-card{border:1px solid var(--pp-border);background:linear-gradient(145deg,#111c31,#0b1324);border-radius:20px;padding:18px}.pp-card h3{margin:0 0 8px;font-size:20px;color:#fff}.pp-card p{margin:0;color:var(--pp-muted)}.pp-stat{font-size:30px;font-weight:900;color:var(--pp-orange);margin-bottom:4px}\n.pp-table-wrap{overflow-x:auto;margin:16px 0;border-radius:16px;border:1px solid var(--pp-border)}.pp-table{width:100%;min-width:720px;border-collapse:collapse;background:#0b1324}.pp-table th{background:linear-gradient(90deg,#ff7a1a,#ff9a3d);color:#111827;font-weight:900;padding:13px 14px;text-align:left;border-bottom:1px solid rgba(255,255,255,.16)}.pp-table td{padding:12px 14px;border-top:1px solid var(--pp-border);color:#d8e0ef;vertical-align:top}.pp-table tr:nth-child(even) td{background:rgba(255,255,255,.025)}.pp-table .rank,.pp-table .num{font-weight:900;color:var(--pp-orange);white-space:nowrap}.pp-table .priority-a{color:#fb7185;font-weight:900}.pp-table .priority-b{color:#58a6ff;font-weight:900}.pp-table .priority-c{color:#2dd4bf;font-weight:900}\n.pp-list{margin:12px 0 0;padding-left:20px;color:#d9e2f2}.pp-list li{margin:7px 0}.pp-unit{border:1px solid var(--pp-border);background:rgba(15,23,42,.7);border-radius:20px;padding:20px;margin:18px 0}.pp-unit h3{margin:0 0 10px;color:#fff;font-size:24px}.pp-unit h3 span{color:var(--pp-orange)}.pp-two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pp-pill-title{color:#fff;font-weight:900;margin:8px 0;display:inline-block;background:#172238;border:1px solid var(--pp-border);padding:6px 10px;border-radius:999px}.pp-formula{font-size:1.02em;color:#fff}.pp-footer{margin-top:30px;border:1px solid var(--pp-border);background:#070d1b;border-radius:24px;padding:22px;text-align:center}.pp-footer-links{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin:14px 0}.pp-footer-link{text-decoration:none!important;color:#fff!important;background:#111c31;border:1px solid var(--pp-border);border-radius:999px;padding:9px 13px;font-weight:800}.pp-footer-link:hover{border-color:var(--pp-orange);color:var(--pp-orange)!important}.pp-small{color:var(--pp-muted);font-size:13px}.pp-highlight{color:var(--pp-orange);font-weight:900}.pp-muted{color:var(--pp-muted)}\nmjx-container{overflow-x:auto;overflow-y:hidden;max-width:100%}\n@media(max-width:760px){.padhaku-blog-wrap{padding:16px 8px;border-radius:16px}.pp-hero,.pp-section{padding:20px;border-radius:20px}.pp-grid,.pp-two{grid-template-columns:1fr}.pp-table{min-width:680px}.pp-title{font-size:34px}}\n</style>\n\n<div class="padhaku-blog-wrap">\n  <div class="pp-container">\n    <header class="pp-hero">\n      <div class="pp-brand"><span>ShikshaSahayak</span><span>Portal</span></div>\n      <div class="pp-kicker">Full Marks Strategy Guide</div>\n      <h1 class="pp-title">GTU BE <strong>Physics</strong></h1>\n      <p class="pp-subtitle">A dark ShikshaSahayak-style exam blog covering syllabus priority, chapter-wise scoring playbook, top questions, formula toolkit, derivations, definitions, and last-minute strategy for GTU Physics.</p>\n      <div class="pp-module-chips">\n        <span class="pp-chip">M1 Properties of Matter</span>\n        <span class="pp-chip">M2 Waves, Motion & Acoustics</span>\n        <span class="pp-chip">M3 Optics</span>\n        <span class="pp-chip">M4 Quantum Physics</span>\n        <span class="pp-chip">M5 Lasers</span>\n        <span class="pp-chip">M6 New Engineering Materials</span>\n      </div>\n      <div class="pp-author-mini">\n        <div class="label">Prepared By:</div>\n        <div class="name">Ayush Pandey</div>\n        <div class="role">Founder, ShikshaSahayak</div>\n        <div class="edu">B.S. Data Science and Applications | IIT Madras</div>\n        <div class="edu">B.E. Electrical Engineering | SSEC, Bhavnagar</div>\n      </div>\n    </header>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Source Base And <span class="accent">Priority Method</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Source</th><th>What Was Used</th><th>Priority Effect</th></tr></thead>\n          <tbody>\n            <tr><td>Latest GTU syllabus</td><td>BE01R00021 Physics, w.e.f. 2024-25.</td><td>Highest authority for topic inclusion.</td></tr>\n            <tr><td>New syllabus papers</td><td>Winter 2024, Summer 2025 and Winter 2025 patterns.</td><td>Highest trend weight.</td></tr>\n            <tr><td>Old syllabus papers</td><td>Used only where the topic still exists in the latest syllabus.</td><td>Trend support only.</td></tr>\n            <tr><td>Unit 1 numericals</td><td>Properties of matter practice problems.</td><td>Numerical preparation support.</td></tr>\n            <tr><td>Scanned Unit 2 material</td><td>Used as study support, not as primary trend data.</td><td>Secondary support.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class="pp-note pink"><strong>Important syllabus correction:</strong> Old Physics papers contain older topics such as viscosity, Josephson junction, SQUID, Hall effect, Drude model and detailed semiconductor topics. Do not treat them as high priority unless the latest syllabus also contains them.</div>\n      <div class="pp-grid">\n        <div class="pp-card"><div class="pp-stat">18%</div><h3>Units 2 to 5</h3><p>Highest scoring block: waves, acoustics, optics, quantum physics and lasers.</p></div>\n        <div class="pp-card"><div class="pp-stat">15%</div><h3>Materials</h3><p>Semiconductors, superconductors and nanomaterials are repeatedly useful.</p></div>\n        <div class="pp-card"><div class="pp-stat">13%</div><h3>Properties</h3><p>Smaller weight, but highly scoring through formulas, derivations and numericals.</p></div>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Subject Preparation <span class="accent">Strategy</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Phase</th><th>Student Action</th><th>Output By End</th></tr></thead>\n          <tbody>\n            <tr><td class="rank">Phase 1: Syllabus lock</td><td>Read the six units and mark Units 2 to 5 as the highest-weight block.</td><td>One-page syllabus map.</td></tr>\n            <tr><td class="rank">Phase 2: Formula sheet</td><td>Prepare formulas for elasticity, simple harmonic motion, acoustics, optics, quantum physics, lasers and materials.</td><td>One compact formula page.</td></tr>\n            <tr><td class="rank">Phase 3: Diagram bank</td><td>Practice cantilever, torsional pendulum, piezoelectric oscillator, Newton''''s rings, Michelson interferometer, laser energy levels, P-N junction, Zener regulator and nanomaterial synthesis diagrams.</td><td>Clean diagrams within two minutes.</td></tr>\n            <tr><td class="rank">Phase 4: Derivations</td><td>Write the ten key derivations once by hand.</td><td>Stepwise derivation confidence.</td></tr>\n            <tr><td class="rank">Phase 5: Numericals</td><td>Practice Young''''s modulus, reverberation, ultrasonic depth, Young''''s double slit experiment, de Broglie wavelength, laser photon energy, isotope effect and critical magnetic field.</td><td>Formula plus unit accuracy.</td></tr>\n            <tr><td class="rank">Phase 6: Paper simulation</td><td>Attempt one seventy-mark paper in two and a half hours.</td><td>Speed and question selection control.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class="pp-two">\n        <div class="pp-card">\n          <h3>Tips To Score Full Marks</h3>\n          <ul class="pp-list">\n            <li>Start every numerical with Given, To find, Formula, Substitution and Final answer with unit.</li>\n            <li>For seven-mark derivations, write assumptions and draw the diagram before equations.</li>\n            <li>For optics, label path difference, order number, wavelength, screen distance and slit separation.</li>\n            <li>For quantum and laser questions, define every symbol immediately after writing the equation.</li>\n          </ul>\n        </div>\n        <div class="pp-card">\n          <h3>Universal Seven-Mark Frame</h3>\n          <p>Diagram first, principle second, derivation or working third, result fourth, applications or limitations last. This is the safest Physics answer pattern.</p>\n        </div>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Latest Syllabus <span class="accent">Blueprint</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Unit</th><th>Weight</th><th>Core Exam Demand</th><th>Priority</th></tr></thead>\n          <tbody>\n            <tr><td>1. Properties of Matter</td><td>13%</td><td>Stress, strain, Hooke''''s law, Young''''s modulus by cantilever depression, uniform and non-uniform bending, I-shaped girders, torsional pendulum and rigidity modulus.</td><td>High</td></tr>\n            <tr><td>2. Waves, Motion and Acoustics</td><td>18%</td><td>SHM, damped and forced vibration, resonance, wave motion, reverberation, Sabine formula, building acoustics, ultrasonics and non-destructive testing.</td><td>Very High</td></tr>\n            <tr><td>3. Optics</td><td>18%</td><td>Huygens principle, superposition, interference, Young''''s double slit experiment, Newton''''s rings, Michelson interferometer, diffraction, grating and resolving power.</td><td>Very High</td></tr>\n            <tr><td>4. Quantum Physics</td><td>18%</td><td>Black body radiation, Planck law, de Broglie waves, wave function, uncertainty principle, Schrodinger equations, particle in a box, tunneling and STM.</td><td>Very High</td></tr>\n            <tr><td>5. Lasers</td><td>18%</td><td>Laser properties, Einstein coefficients, absorption, spontaneous and stimulated emission, population inversion, He-Ne laser, Ruby laser and applications.</td><td>Very High</td></tr>\n            <tr><td>6. New Engineering Materials</td><td>15%</td><td>Semiconductors, P-type and N-type materials, P-N junction, Zener diode, superconductors, Meissner effect, Type I/II superconductors, nanomaterials, ball milling and PVD.</td><td>Very High</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Weighted Topic <span class="accent">Heat Map</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Rank</th><th>Topic Cluster</th><th>HOD Signal</th><th>Student Action</th></tr></thead>\n          <tbody>\n            <tr><td class="num">1</td><td>Semiconductors and Zener diode</td><td>Appears in new papers and strongly in old valid material.</td><td>Prepare P-type, N-type, P-N junction and Zener regulator.</td></tr>\n            <tr><td class="num">2</td><td>Superconductors and critical parameters</td><td>Repeated numericals and definitions.</td><td>Prepare isotope effect, Meissner effect and Type I/Type II comparison.</td></tr>\n            <tr><td class="num">3</td><td>Lasers and Einstein coefficients</td><td>Very frequent long-answer zone.</td><td>Prepare emission processes, population inversion, Ruby laser and Einstein relation.</td></tr>\n            <tr><td class="num">4</td><td>Ultrasonics and non-destructive testing</td><td>High repeat from new and old valid papers.</td><td>Prepare piezoelectric method, depth numericals and industrial uses.</td></tr>\n            <tr><td class="num">5</td><td>Interference and Young''''s double slit experiment</td><td>Core optics plus numericals.</td><td>Prepare fringe width, intensity and interference conditions.</td></tr>\n            <tr><td class="num">6</td><td>Cantilever, bending and Young''''s modulus</td><td>Direct seven-mark derivation and numerical cluster.</td><td>Practice derivation and Unit 1 numericals.</td></tr>\n            <tr><td class="num">7</td><td>Simple harmonic motion and energy</td><td>Repeated seven-mark answer.</td><td>Prepare differential equation and energy proof.</td></tr>\n            <tr><td class="num">8</td><td>Reverberation and building acoustics</td><td>Numerical plus theory hybrid.</td><td>Use Sabine formula and remedies table.</td></tr>\n            <tr><td class="num">9</td><td>Schrodinger equation and particle in a box</td><td>Core quantum derivation.</td><td>Write all symbols and boundary conditions.</td></tr>\n            <tr><td class="num">10</td><td>Nanomaterials</td><td>New syllabus repeated material topic.</td><td>Prepare ball milling, physical vapor deposition and applications.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class="pp-note blue"><strong>Paper pattern clue:</strong> New papers follow a 70-mark structure with Question 1 compulsory and internal options in later questions. Expect mixed units, not one chapter at a time.</div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Chapter-Wise Important Topics And <span class="accent">Repeated Questions</span></h2>\n      <div class="pp-unit">\n        <h3><span>Unit 1:</span> Properties of Matter (13%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>Stress, strain, Hooke''''s law and elastic constants.</li><li>Young''''s modulus by cantilever depression.</li><li>Uniform and non-uniform bending.</li><li>Torsional pendulum and rigidity modulus.</li><li>Elastic hysteresis, after-effect and fatigue.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>Define stress, strain and Young''''s modulus with units.</li><li>Derive depression at the free end of a loaded cantilever.</li><li>Derive Young''''s modulus by uniform/non-uniform bending.</li><li>Explain torsional pendulum and twisting couple per unit twist.</li></ul></div></div>\n      </div>\n      <div class="pp-unit">\n        <h3><span>Unit 2:</span> Waves, Motion and Acoustics (18%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>SHM equation, velocity, acceleration and energy.</li><li>Damped/undamped vibration and resonance.</li><li>Reverberation, absorption coefficient and Sabine formula.</li><li>Ultrasonic waves, piezoelectric generation and NDT.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>Derive differential equation of SHM and energy relation.</li><li>Explain damped vibration, forced vibration and resonance.</li><li>Solve reverberation time numericals using Sabine formula.</li><li>Explain piezoelectric production of ultrasonics with applications.</li></ul></div></div>\n      </div>\n      <div class="pp-unit">\n        <h3><span>Unit 3:</span> Optics (18%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>Huygens principle and superposition.</li><li>Constructive/destructive interference.</li><li>Young''''s double slit experiment and fringe width.</li><li>Newton''''s rings, Michelson interferometer and grating.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>Derive fringe width or intensity in YDSE.</li><li>Derive radius of bright/dark Newton''''s rings.</li><li>Differentiate interference and diffraction.</li><li>Explain grating and resolving power.</li></ul></div></div>\n      </div>\n      <div class="pp-unit">\n        <h3><span>Unit 4:</span> Quantum Physics (18%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>Black body radiation and Planck law.</li><li>Wave-particle duality and de Broglie matter waves.</li><li>Wave function and physical significance.</li><li>Uncertainty principle, Schrodinger equations and particle in a box.</li><li>Quantum tunneling and STM.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>State Planck law and black body radiation basics.</li><li>Derive de Broglie wavelength relation.</li><li>Derive time-independent Schrodinger equation.</li><li>Derive energy levels for particle in a box.</li></ul></div></div>\n      </div>\n      <div class="pp-unit">\n        <h3><span>Unit 5:</span> Lasers (18%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>Laser full form, properties and applications.</li><li>Absorption, spontaneous emission and stimulated emission.</li><li>Einstein coefficients and relation.</li><li>Population inversion, pumping, metastable state and optical resonator.</li><li>He-Ne laser and Ruby laser.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>Differentiate spontaneous and stimulated emission.</li><li>Derive Einstein coefficient relation.</li><li>Explain Ruby laser with schematic and energy-level diagram.</li><li>Solve numericals based on wavelength, frequency and photon energy.</li></ul></div></div>\n      </div>\n      <div class="pp-unit">\n        <h3><span>Unit 6:</span> New Engineering Materials (15%)</h3>\n        <div class="pp-two"><div><span class="pp-pill-title">Must Prepare</span><ul class="pp-list"><li>Intrinsic/extrinsic semiconductors and P-type/N-type materials.</li><li>P-N junction and Zener diode regulator.</li><li>Superconductivity, Meissner effect and Type I/II superconductors.</li><li>Critical temperature, critical field, critical current density and isotope effect.</li><li>Nanomaterials, ball milling and physical vapor deposition.</li></ul></div><div><span class="pp-pill-title">Repeated Questions</span><ul class="pp-list"><li>Compare P-type and N-type semiconductors.</li><li>Explain P-N junction and Zener diode as regulator.</li><li>Describe Meissner effect and superconductor types.</li><li>Explain nanomaterials and ball milling/PVD technique.</li></ul></div></div>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Top 15 <span class="accent">Combined Questions</span></h2>\n      <div class="pp-note"><strong>Priority rule:</strong> Priority A questions should be written first. Priority B should be revised next. Priority C should be used to push from average score to high score.</div>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Priority</th><th>Full Important Question</th><th>Why It Is Highly Recommended</th></tr></thead>\n          <tbody>\n            <tr><td class="priority-a">A1</td><td>Derive the expression for depression at the free end of a loaded cantilever and solve a Young''''s modulus numerical.</td><td>Repeated in new papers and supported by Unit 1 numericals.</td></tr>\n            <tr><td class="priority-a">A2</td><td>Explain SHM, derive its differential equation and obtain velocity, acceleration, kinetic energy and potential energy.</td><td>High-weight Unit 2 and full seven-mark answer.</td></tr>\n            <tr><td class="priority-a">A3</td><td>Explain production of ultrasonic waves by piezoelectric method and write industrial applications including NDT.</td><td>Repeated in new and old valid papers.</td></tr>\n            <tr><td class="priority-a">A4</td><td>Explain Newton''''s rings and derive the radius equations for bright and dark rings.</td><td>Direct seven-mark optics question.</td></tr>\n            <tr><td class="priority-a">A5</td><td>Derive the time-independent Schrodinger wave equation and explain all terms.</td><td>Core quantum derivation.</td></tr>\n            <tr><td class="priority-b">B1</td><td>Explain Einstein coefficients, derive their relation and discuss the physical result.</td><td>Repeated laser derivation and high scoring.</td></tr>\n            <tr><td class="priority-b">B2</td><td>Explain absorption, spontaneous emission, stimulated emission, population inversion and pumping with energy-level diagrams.</td><td>Essential laser theory cluster.</td></tr>\n            <tr><td class="priority-b">B3</td><td>Explain Ruby laser construction and working with schematic diagram and energy-level diagram.</td><td>Repeated long-answer type and diagram-heavy.</td></tr>\n            <tr><td class="priority-b">B4</td><td>Explain intrinsic, extrinsic, P-type and N-type semiconductors with comparison.</td><td>New-syllabus material question and old valid support.</td></tr>\n            <tr><td class="priority-b">B5</td><td>Explain P-N junction diode and Zener diode as a voltage regulator.</td><td>Latest Unit 6 plus direct paper question.</td></tr>\n            <tr><td class="priority-c">C1</td><td>Explain reverberation, absorption coefficient, Sabine formula usage and building-acoustic remedies.</td><td>Numerical plus theory combination.</td></tr>\n            <tr><td class="priority-c">C2</td><td>Explain Young''''s double slit experiment, derive fringe width or intensity and solve a fringe-width numerical.</td><td>Strong optics pattern.</td></tr>\n            <tr><td class="priority-c">C3</td><td>Explain Heisenberg uncertainty principle and de Broglie matter waves with numericals.</td><td>Quantum short and long question support.</td></tr>\n            <tr><td class="priority-c">C4</td><td>Explain superconductivity, Meissner effect, critical parameters, isotope effect and Type I/Type II superconductors.</td><td>Very repeated in old valid material and new papers.</td></tr>\n            <tr><td class="priority-c">C5</td><td>Explain nanomaterials, ball milling, physical vapor deposition and applications.</td><td>New-syllabus recurring materials topic.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Last-Minute <span class="accent">Skip List</span></h2>\n      <div class="pp-note pink"><strong>Disclaimer: skip on your own risk.</strong> This list is only for very less prepared students. A university paper can still surprise you.</div>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Can Skip First</th><th>Reason</th><th>Safer Minimum</th></tr></thead>\n          <tbody>\n            <tr><td>Detailed viscosity and Poiseuille-flow topics</td><td>Visible in older Physics material, not part of the latest six-unit syllabus.</td><td>Do only if your teacher emphasized it.</td></tr>\n            <tr><td>Josephson junction, SQUID, Cooper pairs and full BCS theory</td><td>Older superconductivity depth; latest syllabus asks properties, Meissner effect, types and applications.</td><td>Know Meissner effect and critical parameters first.</td></tr>\n            <tr><td>Classical free electron theory, Drude model, Hall effect and Fermi golden rule</td><td>Old Physics-2 material, not core in latest BE01R00021 syllabus.</td><td>Focus on carriers, bands, band gap and P/N-type materials.</td></tr>\n            <tr><td>Solar cell, exciton, photoconductivity and semiconductor laser depth</td><td>Older semiconductor-depth topics; latest syllabus focuses on semiconductor materials, P-N junction and Zener diode.</td><td>Prepare P-N junction, Zener and band-gap basics.</td></tr>\n            <tr><td>Sabine formula derivation</td><td>Latest syllabus mentions Sabine formula usage and excludes derivation.</td><td>Memorize formula and practice numericals.</td></tr>\n            <tr><td>Acoustic grating and magnetostriction method</td><td>Old-paper topics; latest syllabus lists piezoelectric method, detection and Kundt''''s tube.</td><td>Prepare piezoelectric method and ultrasonic applications.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Formula And Theorem <span class="accent">Toolkit</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Topic</th><th>Formula</th><th>Exam Use</th></tr></thead>\n          <tbody>\n            <tr><td>Stress and strain</td><td class="pp-formula">Stress: \(\sigma=\frac{F}{A}\); Strain: \(\epsilon=\frac{\Delta L}{L}\)</td><td>Definitions and wire-extension numericals.</td></tr>\n            <tr><td>Young''''s modulus</td><td class="pp-formula">\(Y=\frac{\text{Stress}}{\text{Strain}}=\frac{FL}{A\Delta L}\)</td><td>Properties of matter numericals.</td></tr>\n            <tr><td>Bending moment</td><td class="pp-formula">\(M=\frac{YI}{R}\), rectangular beam: \(I=\frac{bd^3}{12}\), circular beam: \(I=\frac{\pi r^4}{4}\)</td><td>Uniform and non-uniform bending.</td></tr>\n            <tr><td>Cantilever depression</td><td class="pp-formula">\(\delta=\frac{Wl^3}{3YI}\); for rectangular beam: \(\delta=\frac{4Wl^3}{Ybd^3}\)</td><td>Very important seven-mark derivation.</td></tr>\n            <tr><td>Torsion</td><td class="pp-formula">Couple per unit twist: \(C=\frac{\pi\eta r^4}{2l}\); \(T=2\pi\sqrt{\frac{I}{C}}\)</td><td>Rigidity modulus and torsional pendulum.</td></tr>\n            <tr><td>Simple harmonic motion</td><td class="pp-formula">\(x=A\sin(\omega t+\phi)\); \(a=-\omega^2x\); \(T=\frac{2\pi}{\omega}\)</td><td>Motion and waves.</td></tr>\n            <tr><td>SHM energy</td><td class="pp-formula">\(K=\frac12m\omega^2(A^2-x^2)\), \(U=\frac12m\omega^2x^2\), \(E=\frac12m\omega^2A^2\)</td><td>Energy derivation.</td></tr>\n            <tr><td>Sabine formula</td><td class="pp-formula">\(T=\frac{0.161V}{A}\)</td><td>Reverberation time numericals.</td></tr>\n            <tr><td>Ultrasonic depth</td><td class="pp-formula">\(d=\frac{vt}{2}\); \(\lambda=\frac{v}{f}\)</td><td>SONAR and pulse numericals.</td></tr>\n            <tr><td>Photon and de Broglie</td><td class="pp-formula">\(E=hf=\frac{hc}{\lambda}\); \(\lambda=\frac{h}{p}=\frac{h}{mv}\)</td><td>Laser and quantum numericals.</td></tr>\n            <tr><td>Young''''s double slit</td><td class="pp-formula">\(\beta=\frac{\lambda D}{d}\); \(y_n=\frac{n\lambda D}{d}\)</td><td>Optics numericals.</td></tr>\n            <tr><td>Interference conditions</td><td class="pp-formula">Constructive: path difference \(=n\lambda\); destructive: path difference \(=\frac{(2n+1)\lambda}{2}\)</td><td>Optics theory.</td></tr>\n            <tr><td>Newton''''s rings</td><td class="pp-formula">Dark ring: \(r_n^2=n\lambda R\); bright ring: \(r_n^2=\frac{(2n-1)\lambda R}{2}\)</td><td>Seven-mark derivation.</td></tr>\n            <tr><td>Diffraction grating</td><td class="pp-formula">\(d\sin\theta=n\lambda\); resolving power: \(\frac{\lambda}{\Delta\lambda}=nN\)</td><td>Grating and resolving power.</td></tr>\n            <tr><td>Michelson interferometer</td><td class="pp-formula">Mirror displacement: \(x=\frac{N\lambda}{2}\)</td><td>Interferometer numericals.</td></tr>\n            <tr><td>Piezoelectric frequency</td><td class="pp-formula">\(f_n=\frac{nv}{2t}=\frac{n}{2t}\sqrt{\frac{Y}{\rho}}\)</td><td>Ultrasonic crystal numericals.</td></tr>\n            <tr><td>Uncertainty principle</td><td class="pp-formula">\(\Delta x\Delta p\geq\frac{h}{4\pi}\); \(\Delta E\Delta t\geq\frac{h}{4\pi}\)</td><td>Quantum theory.</td></tr>\n            <tr><td>Particle in a box</td><td class="pp-formula">\(E_n=\frac{n^2h^2}{8mL^2}\)</td><td>Quantum derivation and numericals.</td></tr>\n            <tr><td>Einstein coefficients</td><td class="pp-formula">\(B_{12}=B_{21}\); \(\frac{A_{21}}{B_{21}}=\frac{8\pi hf^3}{c^3}\)</td><td>Laser derivation.</td></tr>\n            <tr><td>Superconductor isotope effect</td><td class="pp-formula">\(T_c\sqrt{M}=\text{constant}\)</td><td>Critical temperature numericals.</td></tr>\n            <tr><td>Critical magnetic field</td><td class="pp-formula">\(H_c(T)=H_c(0)\left[1-\left(\frac{T}{T_c}\right)^2\right]\)</td><td>Superconductivity numericals.</td></tr>\n            <tr><td>Critical current density</td><td class="pp-formula">\(J_c=\frac{I_c}{A}\)</td><td>Superconducting wire numericals.</td></tr>\n            <tr><td>Diode equation</td><td class="pp-formula">\(I=I_0\left(e^{\frac{eV}{\eta kT}}-1\right)\)</td><td>P-N junction characteristic.</td></tr>\n            <tr><td>Zener regulator</td><td class="pp-formula">\(R_S=\frac{V_{in}-V_Z}{I_Z+I_L}\); \(P_Z=V_ZI_Z\)</td><td>Materials unit application.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <h3>Most Important Theorems And Principles</h3>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Theorem / Principle</th><th>Statement</th><th>Where To Use</th></tr></thead>\n          <tbody>\n            <tr><td>Hooke''''s law</td><td>Within elastic limit, stress is directly proportional to strain.</td><td>Elasticity and Young''''s modulus.</td></tr>\n            <tr><td>Huygens principle</td><td>Every point on a wavefront acts as a source of secondary wavelets.</td><td>Interference and diffraction.</td></tr>\n            <tr><td>Superposition principle</td><td>Resultant displacement is the vector sum of individual wave displacements.</td><td>Interference and standing waves.</td></tr>\n            <tr><td>Rayleigh criterion</td><td>Two sources are just resolved when the principal maximum of one falls on the first minimum of the other.</td><td>Resolving power.</td></tr>\n            <tr><td>de Broglie hypothesis</td><td>Every moving material particle has an associated matter wave.</td><td>Wave-particle duality.</td></tr>\n            <tr><td>Heisenberg uncertainty principle</td><td>Position and momentum cannot both be measured with unlimited precision.</td><td>Quantum physics.</td></tr>\n            <tr><td>Meissner effect</td><td>A superconductor expels magnetic flux from its interior below critical temperature.</td><td>Superconductivity.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Most Important <span class="accent">Derivations</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Priority</th><th>Derivation</th><th>Must Include</th></tr></thead>\n          <tbody>\n            <tr><td class="num">1</td><td>Cantilever depression at free end</td><td>Beam diagram, bending equation, moment of inertia and final depression formula.</td></tr>\n            <tr><td class="num">2</td><td>Torsional pendulum and couple per unit twist</td><td>Restoring couple, rigidity modulus and time-period expression.</td></tr>\n            <tr><td class="num">3</td><td>Simple harmonic motion differential equation</td><td>Restoring force, solution, velocity and acceleration.</td></tr>\n            <tr><td class="num">4</td><td>Energy of simple harmonic oscillator</td><td>Kinetic energy, potential energy and total energy constant.</td></tr>\n            <tr><td class="num">5</td><td>Newton''''s rings radius equations</td><td>Path difference, conditions for bright and dark rings.</td></tr>\n            <tr><td class="num">6</td><td>Young''''s double slit experiment fringe width or intensity</td><td>Path difference and maxima/minima conditions.</td></tr>\n            <tr><td class="num">7</td><td>Time-independent Schrodinger wave equation</td><td>Wave equation, de Broglie relation and energy relation.</td></tr>\n            <tr><td class="num">8</td><td>Particle in one-dimensional box energy levels</td><td>Boundary conditions, wave function and quantized energy.</td></tr>\n            <tr><td class="num">9</td><td>Einstein coefficient relation</td><td>Radiation density equilibrium and comparison with Planck law.</td></tr>\n            <tr><td class="num">10</td><td>Zener diode voltage regulator relation</td><td>Input, load, Zener current and series resistance.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Most Important <span class="accent">Definitions</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Definition</th><th>Exam-Ready Meaning</th></tr></thead>\n          <tbody>\n            <tr><td>Stress</td><td>Restoring force per unit area developed inside a body.</td></tr>\n            <tr><td>Strain</td><td>Ratio of change in dimension to original dimension.</td></tr>\n            <tr><td>Young''''s modulus</td><td>Ratio of longitudinal stress to longitudinal strain within elastic limit.</td></tr>\n            <tr><td>Reverberation time</td><td>Time taken for sound intensity to fall to one millionth of its initial value after the source stops.</td></tr>\n            <tr><td>Absorption coefficient</td><td>Ratio of sound energy absorbed by a surface to sound energy incident on it.</td></tr>\n            <tr><td>Ultrasonic waves</td><td>Sound waves with frequency greater than 20 kilohertz.</td></tr>\n            <tr><td>Interference</td><td>Redistribution of light intensity due to superposition of coherent waves.</td></tr>\n            <tr><td>Diffraction</td><td>Bending or spreading of waves around an obstacle or aperture.</td></tr>\n            <tr><td>Wave function</td><td>Mathematical quantity whose squared magnitude gives probability density.</td></tr>\n            <tr><td>Population inversion</td><td>Condition in which higher energy level has more atoms than lower energy level.</td></tr>\n            <tr><td>Metastable state</td><td>Excited state with comparatively long lifetime.</td></tr>\n            <tr><td>Coherence</td><td>Fixed phase relationship between waves.</td></tr>\n            <tr><td>Intrinsic semiconductor</td><td>Pure semiconductor without intentional impurity doping.</td></tr>\n            <tr><td>Extrinsic semiconductor</td><td>Doped semiconductor with added impurity atoms.</td></tr>\n            <tr><td>Meissner effect</td><td>Expulsion of magnetic field from a superconductor below critical temperature.</td></tr>\n            <tr><td>Nanomaterial</td><td>Material with at least one dimension in the nanometer range, generally 1 to 100 nanometers.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Top 30 Must-Do Questions <span class="accent">No Choice To Ignore</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>No.</th><th>Unit</th><th>Question</th></tr></thead>\n          <tbody>\n            <tr><td class="num">1</td><td>Properties of Matter</td><td>Define stress and strain. Discuss relation between longitudinal stress and strain. Describe stress-strain diagram in detail.</td></tr>\n            <tr><td class="num">2</td><td>Properties of Matter</td><td>Derive expression of bending moment of a beam and obtain Young''''s modulus by uniform bending.</td></tr>\n            <tr><td class="num">3</td><td>Properties of Matter</td><td>Derive expression for depression of a cantilever in terms of Young''''s modulus.</td></tr>\n            <tr><td class="num">4</td><td>Properties of Matter</td><td>Derive Young''''s modulus of a beam by non-uniform bending.</td></tr>\n            <tr><td class="num">5</td><td>Properties of Matter</td><td>Obtain time period of a torsional pendulum and torque per unit twist for a cylinder/wire.</td></tr>\n            <tr><td class="num">6</td><td>Waves & Acoustics</td><td>What is damped motion? Derive the differential equation and general solution of damped harmonic motion.</td></tr>\n            <tr><td class="num">7</td><td>Waves & Acoustics</td><td>Solve numericals on reverberation, ultrasonic frequency and SHM displacement, velocity and acceleration.</td></tr>\n            <tr><td class="num">8</td><td>Waves & Acoustics</td><td>Explain sound absorption and factors affecting acoustics of a building with remedies.</td></tr>\n            <tr><td class="num">9</td><td>Waves & Acoustics</td><td>Write properties of ultrasound and distinguish transverse and longitudinal waves.</td></tr>\n            <tr><td class="num">10</td><td>Waves & Acoustics</td><td>Explain piezoelectric method for generating ultrasonic waves with principle, advantages and applications.</td></tr>\n            <tr><td class="num">11</td><td>Optics</td><td>Explain Newton''''s rings setup and how it is used to calculate wavelength of light.</td></tr>\n            <tr><td class="num">12</td><td>Optics</td><td>Explain Young''''s double-slit experiment and its importance in proving wave nature of light.</td></tr>\n            <tr><td class="num">13</td><td>Optics</td><td>Differentiate between Fresnel and Fraunhofer diffraction.</td></tr>\n            <tr><td class="num">14</td><td>Optics</td><td>Describe Michelson interferometer and its applications in precise measurements.</td></tr>\n            <tr><td class="num">15</td><td>Optics</td><td>Explain Rayleigh criterion and its implications for resolving power of gratings.</td></tr>\n            <tr><td class="num">16</td><td>Quantum Physics</td><td>Discuss Planck''''s law of black-body radiation.</td></tr>\n            <tr><td class="num">17</td><td>Quantum Physics</td><td>Write and discuss de Broglie''''s hypothesis.</td></tr>\n            <tr><td class="num">18</td><td>Quantum Physics</td><td>Obtain time-independent and time-dependent Schrodinger equations.</td></tr>\n            <tr><td class="num">19</td><td>Quantum Physics</td><td>Discuss particle in a one-dimensional box in detail.</td></tr>\n            <tr><td class="num">20</td><td>Quantum Physics</td><td>Describe principle, construction, working and uses of Scanning Tunneling Microscope.</td></tr>\n            <tr><td class="num">21</td><td>Lasers</td><td>Explain properties of LASER.</td></tr>\n            <tr><td class="num">22</td><td>Lasers</td><td>Explain Einstein coefficients and derive necessary condition for production of LASER.</td></tr>\n            <tr><td class="num">23</td><td>Lasers</td><td>Explain construction, working, advantages, disadvantages and applications of He-Ne laser.</td></tr>\n            <tr><td class="num">24</td><td>Lasers</td><td>Explain construction, working, advantages, disadvantages and applications of Ruby laser.</td></tr>\n            <tr><td class="num">25</td><td>Lasers</td><td>Compare spontaneous and stimulated emission.</td></tr>\n            <tr><td class="num">26</td><td>New Engineering Materials</td><td>Explain P-N junction diode with working principle and I-V characteristics under forward and reverse bias.</td></tr>\n            <tr><td class="num">27</td><td>New Engineering Materials</td><td>What are superconductors? Discuss key properties of superconductors.</td></tr>\n            <tr><td class="num">28</td><td>New Engineering Materials</td><td>Compare Type-I and Type-II superconductors.</td></tr>\n            <tr><td class="num">29</td><td>New Engineering Materials</td><td>Compare top-down and bottom-up approaches for synthesizing nanomaterials with examples.</td></tr>\n            <tr><td class="num">30</td><td>New Engineering Materials</td><td>Describe ball milling process for nanomaterial synthesis with mechanism, advantages and limitations.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class="pp-section">\n      <h2 class="pp-section-title">Last-Minute Preparation <span class="accent">Strategy</span></h2>\n      <div class="pp-table-wrap">\n        <table class="pp-table">\n          <thead><tr><th>Time Left</th><th>Do This First</th><th>Avoid This</th></tr></thead>\n          <tbody>\n            <tr><td class="rank">Seven days</td><td>Finish Units 2 to 5, then Unit 6, then Unit 1 numericals and derivations.</td><td>Decorative note rewriting.</td></tr>\n            <tr><td class="rank">Three days</td><td>Write top fifteen questions once and revise formulas, diagrams and derivations.</td><td>Starting old-syllabus chapters.</td></tr>\n            <tr><td class="rank">One day</td><td>Revise formula sheet, diagrams, definitions, top derivations and numerical formats.</td><td>Reading full textbooks from page one.</td></tr>\n            <tr><td class="rank">Exam morning</td><td>Only formulas, diagrams, definitions, priority questions and units.</td><td>Learning new derivations.</td></tr>\n            <tr><td class="rank">During exam</td><td>Attempt known questions first, keep numerical units correct and make diagrams large enough.</td><td>Overwriting one answer while leaving another incomplete.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class="pp-note green"><strong>Final HOD advice:</strong> A full-marks Physics answer is not long; it is complete. Correct diagram, correct formula, correct units and clear steps are the real scoring tools.</div>\n      <div class="pp-card">\n        <h3>Golden Rules</h3>\n        <ul class="pp-list">\n          <li>Latest syllabus wins over old-paper habit.</li>\n          <li>Every seven-mark answer needs a clean diagram or equation structure.</li>\n          <li>Every numerical must show units in the final answer.</li>\n          <li>For derivations, do not jump directly to the final formula.</li>\n          <li>For optics, mark path difference and order number clearly.</li>\n          <li>For lasers, draw energy-level diagrams.</li>\n          <li>For materials, use comparison tables and labelled diagrams.</li>\n          <li>Do not ignore definitions because they decide three-mark questions.</li>\n        </ul>\n      </div>\n    </section>\n\n    <footer class="pp-footer">\n      <div class="pp-brand" style="justify-content:center;margin-bottom:8px"><span>ShikshaSahayak</span><span>Portal</span></div>\n      <p class="pp-small">Learn • Prepare • Achieve | GTU BE Physics Full Marks Guide</p>\n      <div class="pp-footer-links">\n        <a class="pp-footer-link" href="https://shikshasahayak.org" target="_blank" rel="noopener">Website</a>\n        <a class="pp-footer-link" href="https://www.instagram.com/padhaku_portal/" target="_blank" rel="noopener">Instagram</a>\n        <a class="pp-footer-link" href="https://chat.whatsapp.com/JKjcvjun6roIkbat7O59uJ" target="_blank" rel="noopener">WA Community</a>\n        <a class="pp-footer-link" href="https://www.whatsapp.com/channel/0029VbCPjEsJf05VIeyIHv2i" target="_blank" rel="noopener">WA Channel</a>\n        <a class="pp-footer-link" href="https://t.me/padhaku_portal" target="_blank" rel="noopener">Telegram</a>\n        <a class="pp-footer-link" href="https://www.linkedin.com/company/padhakuportal/" target="_blank" rel="noopener">LinkedIn</a>\n      </div>\n      <p class="pp-small">© 2026 ShikshaSahayak. All Rights Reserved.</p>\n    </footer>\n  </div>\n</div>\n\n<script>\nwindow.MathJax = {\n  tex: {\n    inlineMath: [[''''\\('''', ''''\\)'''']],\n    displayMath: [[''''\\['''', ''''\\]'''']],\n    processEscapes: true,\n    processEnvironments: true\n  },\n  options: {\n    skipHtmlTags: [''''script'''', ''''noscript'''', ''''style'''', ''''textarea'''', ''''pre'''', ''''code'''']\n  },\n  chtml: {\n    scale: 1.03,\n    mtextInheritFont: false\n  }\n};\n</script>\n<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script>\n\n</body>\n</html>''',
  '\n',
