INSERT OR REPLACE INTO blogs (id, related_document_id, title, content, author, category, tags, thumbnail, status, views, created_at, updated_at) VALUES (
  'blog_b6b6e7a2',
  'doc_29cfa606',
  'BME Full Mark Guide By ShikshaSahayak',
  'replace(''<!doctype html>\012<html lang="en">\012<head>\012  <meta charset="utf-8">\012  <meta name="viewport" content="width=device-width, initial-scale=1">\012  <title>GTU BME Full Marks Guide - ShikshaSahayak</title>\012</head>\012<body style="margin:0;background:#05070d;">\012<style>\012  :root{\012    --pp-bg:#05070d;\012    --pp-surface:#0b1220;\012    --pp-card:#101827;\012    --pp-card-2:#111d31;\012    --pp-text:#f7f7fb;\012    --pp-muted:#b7c2d4;\012    --pp-soft:#7d8aa3;\012    --pp-orange:#ff8a1f;\012    --pp-orange-2:#ffb057;\012    --pp-border:rgba(255,255,255,.11);\012    --pp-green:#37d67a;\012    --pp-red:#ff6b6b;\012    --pp-blue:#61a5ff;\012    --pp-shadow:0 18px 50px rgba(0,0,0,.28);\012  }\012  .pp-wrap{background:radial-gradient(circle at top left,rgba(255,138,31,.16),transparent 34%),radial-gradient(circle at top right,rgba(97,165,255,.10),transparent 30%),var(--pp-bg);color:var(--pp-text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.72;padding:24px 12px;margin:0 auto;box-sizing:border-box;}\012  .pp-container{max-width:1120px;margin:0 auto;}\012  .pp-hero{border:1px solid var(--pp-border);background:linear-gradient(135deg,rgba(16,24,39,.94),rgba(7,12,22,.98));border-radius:22px;padding:34px 24px;box-shadow:var(--pp-shadow);overflow:hidden;position:relative;}\012  .pp-hero:before{content:"";position:absolute;inset:-80px -80px auto auto;width:230px;height:230px;background:rgba(255,138,31,.18);filter:blur(10px);border-radius:50%;}\012  .pp-kicker{display:inline-flex;align-items:center;gap:8px;background:rgba(255,138,31,.12);border:1px solid rgba(255,138,31,.35);color:#ffd5ad;border-radius:999px;padding:6px 12px;font-weight:800;font-size:13px;letter-spacing:.3px;text-transform:uppercase;}\012  .pp-title{font-size:clamp(30px,5vw,54px);line-height:1.07;margin:18px 0 12px;font-weight:950;letter-spacing:0;color:#fff;}\012  .pp-subtitle{font-size:18px;color:var(--pp-muted);max-width:820px;margin:0;}\012  .pp-meta{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px;}\012  .pp-pill{border:1px solid var(--pp-border);background:rgba(255,255,255,.05);border-radius:999px;padding:8px 12px;color:#dfe7f5;font-size:14px;font-weight:700;}\012  .pp-author{margin-top:22px;display:inline-block;border-left:4px solid var(--pp-orange);background:rgba(255,255,255,.055);border-radius:12px;padding:12px 16px;color:#e8eef8;}\012  .pp-author strong{display:block;color:#fff;font-size:16px;}\012  .pp-section{margin-top:24px;border:1px solid var(--pp-border);background:rgba(16,24,39,.88);border-radius:18px;padding:22px;box-shadow:0 10px 35px rgba(0,0,0,.18);}\012  .pp-section h2{font-size:clamp(24px,3vw,34px);line-height:1.18;margin:0 0 14px;color:#fff;}\012  .pp-section h3{font-size:21px;margin:22px 0 10px;color:#fff;}\012  .pp-section p{color:var(--pp-muted);margin:8px 0 12px;}\012  .pp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:16px;}\012  .pp-grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:16px;}\012  .pp-card{background:linear-gradient(180deg,var(--pp-card),rgba(10,16,29,.95));border:1px solid var(--pp-border);border-radius:16px;padding:18px;}\012  .pp-card h3,.pp-card h4{margin:0 0 8px;color:#fff;}\012  .pp-card p,.pp-card li{color:var(--pp-muted);}\012  .pp-stat{font-size:36px;font-weight:950;color:var(--pp-orange);line-height:1;margin-bottom:8px;}\012  .pp-list{padding-left:20px;margin:10px 0;color:var(--pp-muted);}\012  .pp-list li{margin:7px 0;}\012  .pp-table-wrap{overflow-x:auto;margin:16px 0;border-radius:14px;border:1px solid var(--pp-border);}\012  .pp-table{width:100%;border-collapse:collapse;min-width:760px;background:#0b1220;}\012  .pp-table th{background:linear-gradient(180deg,#ff8a1f,#e86f00);color:#101010;text-align:left;font-size:14px;padding:13px 14px;font-weight:950;vertical-align:top;}\012  .pp-table td{border-top:1px solid var(--pp-border);padding:13px 14px;color:#d8e1ef;vertical-align:top;}\012  .pp-table tr:nth-child(even) td{background:rgba(255,255,255,.025);}\012  .pp-priority{display:inline-block;border-radius:999px;padding:4px 9px;font-size:12px;font-weight:900;white-space:nowrap;}\012  .high{background:rgba(255,138,31,.16);color:#ffc38b;border:1px solid rgba(255,138,31,.35);}\012  .very{background:rgba(55,214,122,.14);color:#94f0bd;border:1px solid rgba(55,214,122,.35);}\012  .medium{background:rgba(97,165,255,.14);color:#a9cdff;border:1px solid rgba(97,165,255,.35);}\012  .pp-callout{border:1px solid rgba(255,138,31,.35);background:linear-gradient(135deg,rgba(255,138,31,.13),rgba(255,255,255,.035));border-radius:16px;padding:16px;margin:14px 0;color:#ffe4c9;}\012  .pp-callout strong{color:#fff;}\012  .pp-unit{border:1px solid var(--pp-border);background:rgba(255,255,255,.035);border-radius:16px;padding:18px;margin-top:14px;}\012  .pp-unit h3{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:0 0 10px;}\012  .pp-badge{background:rgba(255,138,31,.16);border:1px solid rgba(255,138,31,.32);color:#ffd1a3;border-radius:999px;padding:4px 9px;font-size:12px;font-weight:900;}\012  .pp-formula{font-size:16px;color:#fff;}\012  .pp-footer{margin-top:24px;border:1px solid var(--pp-border);background:#080d18;border-radius:18px;padding:22px;text-align:center;}\012  .pp-footer p{color:var(--pp-muted);margin:0 0 14px;}\012  .pp-links{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;}\012  .pp-links a{color:#101010!important;background:var(--pp-orange);font-weight:950;text-decoration:none!important;border-radius:999px;padding:10px 14px;display:inline-block;}\012  .pp-links a:hover{background:var(--pp-orange-2);}\012  mjx-container{overflow-x:auto;overflow-y:hidden;max-width:100%;padding:2px 0;}\012  @media (max-width:760px){.pp-wrap{padding:14px 8px}.pp-hero,.pp-section{padding:20px 15px;border-radius:16px}.pp-grid,.pp-grid-2{grid-template-columns:1fr}.pp-table{min-width:700px}.pp-title{font-size:32px}.pp-subtitle{font-size:16px}}\012</style>\012\012<div class="pp-wrap">\012  <div class="pp-container">\012    <section class="pp-hero">\012      <span class="pp-kicker">ShikshaSahayak &bull; Full Marks Guide</span>\012      <h1 class="pp-title">GTU BE Basic Mechanical Engineering</h1>\012      <p class="pp-subtitle">Full Marks Preparation & Paper Analysis Report for <strong>BE01R00081 Basic Mechanical Engineering</strong>, designed for fast revision, question selection, formula clarity, and clean exam presentation.</p>\012      <div class="pp-meta">\012        <span class="pp-pill">Subject: Basic Mechanical Engineering</span>\012        <span class="pp-pill">GTU BE</span>\012        <span class="pp-pill">Latest syllabus focused</span>\012        <span class="pp-pill">Blogger-ready MathJax format</span>\012      </div>\012      <div class="pp-author">\012        <strong>Prepared By: Ayush Pandey</strong>\012        Founder, ShikshaSahayak<br>\012        B.S. Data Science and Applications | IIT Madras<br>\012        B.E. Electrical Engineering | SSEC, Bhavnagar\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Score Strategy Snapshot</h2>\012      <p>The safest full-marks route in BME is to master Units 2 and 3 first because they carry the highest numerical and derivation return. Units 4, 5, 6 and 7 add repeated diagram-based questions, while Unit 8 gives direct marks through definitions and classification.</p>\012      <div class="pp-grid">\012        <div class="pp-card"><div class="pp-stat">42%</div><h3>Units 2 and 3</h3><p>Gas/steam properties plus heat engines and IC engines. Highest numerical and derivation core.</p></div>\012        <div class="pp-card"><div class="pp-stat">30%</div><h3>Units 4, 5 and 7</h3><p>Boilers, compressors, pumps, couplings, clutches and brakes. Strong sketch and comparison questions.</p></div>\012        <div class="pp-card"><div class="pp-stat">28%</div><h3>Units 1, 6 and 8</h3><p>Basic terminology, refrigeration, air conditioning and engineering materials. Good direct scoring topics.</p></div>\012      </div>\012      <div class="pp-callout"><strong>Golden exam rule:</strong> Every machine answer needs a neat labelled sketch. Every numerical needs formula, substitution, final answer and unit.</div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Source Base and Priority Method</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Source</th><th>What Was Used</th><th>Priority Effect</th></tr></thead>\012        <tbody>\012          <tr><td>Latest GTU syllabus</td><td>BE01R00081 Basic Mechanical Engineering, w.e.f. 2024-25.</td><td>Highest authority for topic inclusion.</td></tr>\012          <tr><td>New syllabus papers</td><td>Winter 2024, Summer 2025 and Winter 2025 pattern.</td><td>Highest trend weight.</td></tr>\012          <tr><td>Question bank</td><td>Repeated question clusters and wording.</td><td>Strong repeat confirmation.</td></tr>\012          <tr><td>Old GTU papers</td><td>Used only where the topic still exists in latest syllabus.</td><td>Trend support only.</td></tr>\012          <tr><td>Books and e-notes</td><td>Formula, definition and standard concept support.</td><td>Reference support.</td></tr>\012        </tbody>\012      </table></div>\012      <div class="pp-callout"><strong>Important syllabus correction:</strong> Older BME papers and books may include manufacturing, machine tools, centroid, full fluid mechanics, turbines and measuring instruments. Do not treat them as high priority unless they connect directly to the latest BE01R00081 unit list.</div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Subject Preparation Strategy</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Phase</th><th>Student Action</th><th>Output By End</th></tr></thead>\012        <tbody>\012          <tr><td>Phase 1: Syllabus lock</td><td>Mark Units 2 and 3 as the numerical and derivation core.</td><td>One-page syllabus map.</td></tr>\012          <tr><td>Phase 2: Formula bank</td><td>Prepare gas-process, steam, cycle, engine, compressor and refrigeration formulas.</td><td>One compact formula sheet.</td></tr>\012          <tr><td>Phase 3: Diagram bank</td><td>Practise systems, cycles, boilers, compressor diagrams, pumps, VCR cycle, clutches, brakes and drives.</td><td>Clean labelled diagrams within two minutes.</td></tr>\012          <tr><td>Phase 4: Numericals</td><td>Practise non-flow processes, steam tables, Otto/Diesel/Carnot/Rankine cycles, engine performance, compressor work and COP.</td><td>Formula plus unit confidence.</td></tr>\012          <tr><td>Phase 5: Long answers</td><td>Write at least twenty seven-mark answers using diagram, working, formulas and applications.</td><td>Exam-ready answer set.</td></tr>\012          <tr><td>Phase 6: Paper simulation</td><td>Attempt one seventy-mark paper in two and a half hours.</td><td>Speed and question selection control.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Paper Presentation Tips</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Question Type</th><th>Winning Structure</th><th>Marks Trick</th></tr></thead>\012        <tbody>\012          <tr><td>Three marks</td><td>Definition, small diagram or formula, two exact points.</td><td>Be direct and avoid story writing.</td></tr>\012          <tr><td>Four marks numerical</td><td>Given, formula, substitution and final answer.</td><td>Units and conversions matter.</td></tr>\012          <tr><td>Four marks theory</td><td>Diagram or comparison table plus explanation.</td><td>Underline key terms.</td></tr>\012          <tr><td>Seven marks derivation</td><td>Diagram, assumptions, equation steps, boxed result.</td><td>Do not skip intermediate steps.</td></tr>\012          <tr><td>Seven marks machine</td><td>Construction, working, labelled sketch, advantages and applications.</td><td>Sketch carries marks.</td></tr>\012          <tr><td>Steam-table numerical</td><td>State table values clearly before substitution.</td><td>Use correct dryness fraction relation.</td></tr>\012        </tbody>\012      </table></div>\012      <div class="pp-callout"><strong>Universal seven-mark frame:</strong> Sketch or cycle diagram first, principle second, working or derivation third, final expression fourth, applications or comparison last.</div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Latest Syllabus Blueprint</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Unit</th><th>Weight</th><th>Core Exam Demand</th><th>Priority</th></tr></thead>\012        <tbody>\012          <tr><td>1. Basic Terminology and Energy</td><td>14%</td><td>Prime movers, force, pressure, energy, work, power, system, heat, temperature, specific heat, process, cycle, internal energy, enthalpy, Zeroth law, First law, energy sources and environmental issues.</td><td><span class="pp-priority high">High</span></td></tr>\012          <tr><td>2. Properties of Gases and Steam</td><td>22%</td><td>Gas laws, gas constant, relation between specific heats, non-flow processes, steam formation, types of steam, enthalpy, specific volume, internal energy, dryness fraction, steam tables and steam calorimeters.</td><td><span class="pp-priority very">Very High</span></td></tr>\012          <tr><td>3. Heat Engines and IC Engines</td><td>20%</td><td>Carnot, Rankine, Otto and Diesel cycles, classification of heat engines, four-stroke and two-stroke petrol/diesel engines, indicated power, brake power and efficiencies.</td><td><span class="pp-priority very">Very High</span></td></tr>\012          <tr><td>4. Steam Boilers</td><td>10%</td><td>Classification, Cochran boiler, Lancashire boiler, Babcock and Wilcox boiler, boiler mountings and accessories.</td><td><span class="pp-priority high">High</span></td></tr>\012          <tr><td>5. Air Compressors and Pumps</td><td>10%</td><td>Reciprocating and rotary compressors, multistage compression, reciprocating, rotary and centrifugal pumps, priming.</td><td><span class="pp-priority high">High</span></td></tr>\012          <tr><td>6. Refrigeration and Air Conditioning</td><td>8%</td><td>Refrigerant, vapor compression system, vapor absorption system, domestic refrigerator, window and split air conditioners.</td><td><span class="pp-priority medium">Medium-High</span></td></tr>\012          <tr><td>7. Couplings, Clutches, Brakes and Power Transmission</td><td>10%</td><td>Box, flange, pin flexible, universal and Oldham couplings, disc and centrifugal clutches, block, shoe, band and disc brakes, belt, chain, friction and gear drives.</td><td><span class="pp-priority high">High</span></td></tr>\012          <tr><td>8. Engineering Materials</td><td>6%</td><td>Ferrous, non-ferrous and non-metallic materials, timber, abrasives, silica, ceramics, glass, graphite, diamond, plastic and polymer, properties and applications.</td><td><span class="pp-priority medium">Medium</span></td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Weighted Topic Heat Map</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Rank</th><th>Topic Cluster</th><th>HOD Signal</th><th>Student Action</th></tr></thead>\012        <tbody>\012          <tr><td>1</td><td>Thermodynamic terms and laws</td><td>Repeated compulsory-style area.</td><td>Prepare systems, laws, heat, work, enthalpy and energy sources.</td></tr>\012          <tr><td>2</td><td>Gas laws and non-flow processes</td><td>Highest numerical return.</td><td>Practise isothermal, adiabatic, polytropic and constant-pressure problems.</td></tr>\012          <tr><td>3</td><td>Steam properties and calorimeters</td><td>Repeated steam-table long numericals.</td><td>Master dryness fraction, throttling calorimeter and formulas for \(h\), \(u\) and \(v\).</td></tr>\012          <tr><td>4</td><td>Otto, Diesel, Carnot and Rankine cycles</td><td>Very common derivation and numerical area.</td><td>Prepare diagrams and efficiency formulas.</td></tr>\012          <tr><td>5</td><td>Internal combustion engines</td><td>Repeated theory and performance numericals.</td><td>Prepare SI vs CI, four-stroke engine, BP, IP and efficiencies.</td></tr>\012          <tr><td>6</td><td>Boilers, mountings and accessories</td><td>Strong theory/sketch area.</td><td>Prepare Babcock and Wilcox, Cochran and mountings/functions.</td></tr>\012          <tr><td>7</td><td>Compressors and pumps</td><td>Repeated practical numerical/theory unit.</td><td>Prepare multistage compression, priming and pump comparisons.</td></tr>\012          <tr><td>8</td><td>Refrigeration and air conditioning</td><td>Repeated VCR and split AC questions.</td><td>Prepare COP, TR, VCR, VAR, window and split AC.</td></tr>\012          <tr><td>9</td><td>Couplings, clutches, brakes and drives</td><td>Very frequent short and sketch questions.</td><td>Prepare centrifugal clutch, shoe brake and drive comparison.</td></tr>\012          <tr><td>10</td><td>Engineering materials</td><td>Low weight but direct marks.</td><td>Prepare property definitions and material classification.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Chapter-Wise Important Topics And Repeated Questions</h2>\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 1 &bull; 14%</span> Basic Terminology and Energy</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Thermodynamic system, boundary, surroundings, process and cycle.</li><li>Open, closed and isolated systems with examples.</li><li>Zeroth law and First law of thermodynamics.</li><li>Internal energy, enthalpy, heat, work and power.</li><li>Renewable and non-renewable energy sources.</li><li>Global warming and ozone depletion.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Explain open, closed and isolated thermodynamic systems with neat sketches.</li><li>State Zeroth law and First law of thermodynamics.</li><li>Differentiate renewable and non-renewable energy sources with examples.</li><li>Explain global warming, causes, effects and control measures.</li><li>Define prime mover, system, process, cycle, internal energy and enthalpy.</li><li>Explain advantages and disadvantages of solar energy.</li></ul></div></div><p><strong>Answer-writing note:</strong> Diagrams and definitions decide marks. Keep thermodynamic system sketches clean.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 2 &bull; 22%</span> Properties of Gases and Steam</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Boyle''''s law, Charles''''s law, Gay-Lussac''''s law and Avogadro''''s law.</li><li>Characteristic gas equation and gas constant.</li><li>Relation between \(C_p\) and \(C_v\).</li><li>Constant volume, constant pressure, isothermal, adiabatic and polytropic processes.</li><li>Steam formation and types of steam.</li><li>Dryness fraction, steam tables and calorimeters.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Derive the characteristic gas equation \(PV=mRT\).</li><li>Prove that \(C_p-C_v=R\).</li><li>Derive work done and heat transfer relations for non-flow processes.</li><li>Explain throttling calorimeter and state its limitations.</li><li>Determine enthalpy, volume, entropy and internal energy of wet or superheated steam.</li><li>Solve gas-process numericals involving work, heat, internal energy and enthalpy.</li></ul></div></div><p><strong>Answer-writing note:</strong> This is the highest-weight unit. Practise numericals daily; steam tables are allowed, but method must be clear.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 3 &bull; 20%</span> Heat Engines and Internal Combustion Engines</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Heat engine, heat engine cycle and working substances.</li><li>Carnot, Rankine, Otto and Diesel cycles.</li><li>Air-standard efficiency of Otto and Diesel cycles.</li><li>Two-stroke and four-stroke petrol and diesel engines.</li><li>Spark ignition and compression ignition engines.</li><li>Brake power, indicated power, thermal efficiencies and specific fuel consumption.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Derive air-standard efficiency of Otto cycle.</li><li>Derive air-standard efficiency of Diesel cycle.</li><li>State assumptions and limitations of Carnot cycle.</li><li>Differentiate spark ignition engine and compression ignition engine.</li><li>Explain four-stroke diesel engine with neat sketch.</li><li>Solve internal combustion engine performance numericals.</li></ul></div></div><p><strong>Answer-writing note:</strong> For engine questions, draw a labelled cycle diagram or engine schematic before explanation.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 4 &bull; 10%</span> Steam Boilers</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Boiler definition and classification.</li><li>Cochran boiler.</li><li>Lancashire boiler.</li><li>Babcock and Wilcox boiler.</li><li>Boiler mountings and accessories.</li><li>Essential requirements of a good boiler.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Explain working of Babcock and Wilcox boiler with neat sketch.</li><li>Explain working of Cochran boiler with neat sketch.</li><li>Differentiate fire-tube boiler and water-tube boiler.</li><li>Define boiler and write essential requirements of a good boiler.</li><li>Differentiate boiler mountings and accessories.</li><li>Enlist boiler mountings and accessories with functions.</li></ul></div></div><p><strong>Answer-writing note:</strong> Boilers are practical-hour syllabus topics but appear strongly in theory papers. Prepare labelled diagrams.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 5 &bull; 10%</span> Air Compressors and Pumps</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Reciprocating and rotary air compressors.</li><li>Positive displacement and rotodynamic compressors.</li><li>Need and significance of multistage compression.</li><li>Single-stage and double-acting compressor terms.</li><li>Centrifugal, reciprocating and rotary pumps.</li><li>Priming of centrifugal pump.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Explain need of multistaging in reciprocating air compressor with pressure-volume diagram.</li><li>Differentiate reciprocating and rotary compressor.</li><li>Define double-acting compressor, multistage compressor, swept volume and pressure ratio.</li><li>Explain priming and why it is required in centrifugal pump.</li><li>Compare reciprocating pump and centrifugal pump.</li><li>Solve compressor work and dimensions numericals.</li></ul></div></div><p><strong>Answer-writing note:</strong> Compressors and pumps are formula-plus-diagram topics. Use pressure-volume diagrams whenever asked.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 6 &bull; 8%</span> Refrigeration and Air Conditioning</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Refrigerant and refrigeration effect.</li><li>Coefficient of performance and ton of refrigeration.</li><li>Vapor compression refrigeration system.</li><li>Vapor absorption refrigeration system.</li><li>Domestic refrigerator.</li><li>Window and split air conditioners.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Define refrigeration, refrigeration effect and coefficient of performance.</li><li>Explain vapor compression refrigeration system with schematic and charts.</li><li>Explain vapor absorption refrigeration system with neat sketch.</li><li>Explain working of split air conditioner.</li><li>Show VCR cycle on \(T-s\) and \(p-h\) diagrams.</li><li>Solve coefficient of performance and ton of refrigeration numericals.</li></ul></div></div><p><strong>Answer-writing note:</strong> Even with 8% weight, VCR system is a repeated 7-mark answer. Learn one perfect labelled diagram.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 7 &bull; 10%</span> Couplings, Clutches, Brakes and Power Transmission</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Shaft and axle.</li><li>Rigid and flexible couplings.</li><li>Flange, universal, Oldham and pin-type flexible coupling.</li><li>Disc clutch and centrifugal clutch.</li><li>Block, shoe, band and disc brakes.</li><li>Belt, chain, friction and gear drives.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Differentiate clutch, coupling and brake.</li><li>Differentiate rigid coupling and flexible coupling.</li><li>Explain centrifugal clutch with neat sketch.</li><li>Explain internal expanding shoe brake with neat sketch.</li><li>Compare belt drive, chain drive and gear drive.</li><li>State types and applications of couplings, clutches and brakes.</li></ul></div></div><p><strong>Answer-writing note:</strong> This unit is diagram-friendly and repeatedly asked. Prepare compact sketches and comparison tables.</p></div>\012\012      <div class="pp-unit"><h3><span class="pp-badge">Unit 8 &bull; 6%</span> Engineering Materials</h3><div class="pp-grid-2"><div><h4>Most Important Topics</h4><ul class="pp-list"><li>Ferrous and non-ferrous metals.</li><li>Non-metallic materials.</li><li>Elasticity, plasticity, ductility, hardness, toughness, brittleness and resilience.</li><li>Timber, abrasives, ceramics and glass.</li><li>Graphite, diamond, plastics and polymers.</li><li>Applications of engineering materials.</li></ul></div><div><h4>Most Repeated Questions</h4><ul class="pp-list"><li>Define hardness, toughness, ductility and elasticity.</li><li>Differentiate elasticity and plasticity and explain resilience.</li><li>Classify engineering materials into ferrous, non-ferrous and non-metallic materials.</li><li>Explain non-metallic materials with practical importance.</li><li>Write properties and applications of cast iron or non-ferrous materials.</li><li>State applications of plastics, polymers, ceramics, graphite and diamond.</li></ul></div></div><p><strong>Answer-writing note:</strong> This is a low-weight unit but good for direct 3- and 4-mark answers.</p></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Top 15 Combined Questions</h2>\012      <p>Priority A questions should be written first. Priority B should be revised next. Priority C should be used to push the score upward after the core is ready.</p>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Priority</th><th>Full Important Question</th><th>Why It Is Highly Recommended</th></tr></thead>\012        <tbody>\012          <tr><td>A1</td><td>Derive the characteristic gas equation \(PV=mRT\) and prove that \(C_p-C_v=R\).</td><td>Directly repeated and central to Unit 2.</td></tr>\012          <tr><td>A2</td><td>Solve non-flow process numericals for isothermal, adiabatic and polytropic processes including work done, heat exchange, internal energy and enthalpy.</td><td>Most reliable numerical cluster.</td></tr>\012          <tr><td>A3</td><td>Explain throttling calorimeter and determine dryness fraction using steam-table data.</td><td>Repeated steam question and steam tables are allowed.</td></tr>\012          <tr><td>A4</td><td>Derive air-standard efficiency of Otto cycle and Diesel cycle.</td><td>High-value Unit 3 derivation.</td></tr>\012          <tr><td>A5</td><td>Explain four-stroke diesel or petrol engine and compare spark ignition and compression ignition engines.</td><td>Repeated engine theory and comparison.</td></tr>\012          <tr><td>B1</td><td>Explain open, closed and isolated systems with sketches and state Zeroth law and First law of thermodynamics.</td><td>Compulsory-type short question area.</td></tr>\012          <tr><td>B2</td><td>Explain Babcock and Wilcox boiler with neat sketch and list mountings and accessories with functions.</td><td>Repeated practical-theory topic.</td></tr>\012          <tr><td>B3</td><td>Explain need of multistage compression with pressure-volume diagram and compare reciprocating and rotary compressors.</td><td>Strong Unit 5 pattern.</td></tr>\012          <tr><td>B4</td><td>Explain vapor compression refrigeration system with schematic, temperature-entropy diagram and pressure-enthalpy diagram.</td><td>Repeated Unit 6 long answer.</td></tr>\012          <tr><td>B5</td><td>Explain centrifugal clutch and internal expanding shoe brake with neat sketches.</td><td>Repeated high-return Unit 7 diagrams.</td></tr>\012          <tr><td>C1</td><td>Explain global warming, ozone depletion and renewable/non-renewable energy sources.</td><td>Good for 4- and 7-mark theory.</td></tr>\012          <tr><td>C2</td><td>Explain Carnot cycle assumptions and limitations and solve Carnot efficiency numerical.</td><td>Useful cycle backup topic.</td></tr>\012          <tr><td>C3</td><td>Compare centrifugal and reciprocating pumps and explain priming.</td><td>Repeated short/theory area.</td></tr>\012          <tr><td>C4</td><td>Compare belt drive, chain drive and gear drive with applications.</td><td>Very common power transmission question.</td></tr>\012          <tr><td>C5</td><td>Define engineering material properties and classify ferrous, non-ferrous and non-metallic materials.</td><td>Direct scoring Unit 8 topic.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Last-Minute Skip List</h2>\012      <div class="pp-callout"><strong>Disclaimer:</strong> Skip on your own risk. This list is only for students who are very less prepared at the last moment. A university paper can still surprise you.</div>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Can Skip First</th><th>Reason</th><th>Safer Minimum</th></tr></thead>\012        <tbody>\012          <tr><td>Manufacturing processes such as casting, welding, forging, machining and machine tools</td><td>Common in old BME books and papers, but not present in latest BE01R00081 theory units.</td><td>Skip unless your faculty specifically taught it.</td></tr>\012          <tr><td>Centroid and moment of inertia full chapter</td><td>Present in some books, but not in latest GTU BME syllabus.</td><td>Only know moment of inertia if your class connects it to mechanics examples.</td></tr>\012          <tr><td>Detailed fluid mechanics beyond pumps</td><td>Latest syllabus asks pumps and priming, not full Bernoulli, turbines or pipe-flow theory.</td><td>Prepare centrifugal and reciprocating pumps.</td></tr>\012          <tr><td>Steam turbines and gas turbines in depth</td><td>Latest syllabus includes heat-engine cycles but not detailed turbine chapters.</td><td>Know Rankine cycle basics only.</td></tr>\012          <tr><td>Detailed refrigeration psychrometry</td><td>Latest syllabus asks VCR, VAR, domestic refrigerator, window and split air conditioners.</td><td>Prepare COP, TR and simple AC working.</td></tr>\012          <tr><td>Advanced material science details and heat treatment</td><td>Latest syllabus asks types, properties and applications of materials.</td><td>Prepare definitions and classification.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Formula And Theorem Toolkit</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Topic</th><th>Proper Mathematical Form</th><th>Exam Use</th></tr></thead>\012        <tbody>\012          <tr><td>Pressure</td><td class="pp-formula">\(P=\frac{F}{A}\)</td><td>Basic terminology and compressor/pump questions.</td></tr>\012          <tr><td>Power</td><td class="pp-formula">\(P=\frac{W}{t}\)</td><td>Engine and machine calculations.</td></tr>\012          <tr><td>Ideal gas equation</td><td class="pp-formula">\(PV=mRT\)</td><td>Gas law numericals.</td></tr>\012          <tr><td>Specific heat relation</td><td class="pp-formula">\(C_p-C_v=R,\quad \gamma=\frac{C_p}{C_v}\)</td><td>Gas-process calculations.</td></tr>\012          <tr><td>Constant volume process</td><td class="pp-formula">\(W=0,\quad Q=\Delta U=mC_v(T_2-T_1)\)</td><td>Non-flow process numericals.</td></tr>\012          <tr><td>Constant pressure process</td><td class="pp-formula">\(W=P(V_2-V_1)=mR(T_2-T_1)\)<br>\(Q=mC_p(T_2-T_1)\)</td><td>Gas-process numericals.</td></tr>\012          <tr><td>Isothermal process</td><td class="pp-formula">\(PV=\text{constant}\)<br>\(W=mRT\ln\left(\frac{V_2}{V_1}\right)=mRT\ln\left(\frac{P_1}{P_2}\right)\)<br>\(\Delta U=0\)</td><td>Compressor and gas-process questions.</td></tr>\012          <tr><td>Adiabatic process</td><td class="pp-formula">\(PV^{\gamma}=\text{constant}\)<br>\(TV^{\gamma-1}=\text{constant}\)<br>\(W=\frac{mR(T_1-T_2)}{\gamma-1}\)</td><td>Derivation and numericals.</td></tr>\012          <tr><td>Polytropic process</td><td class="pp-formula">\(PV^n=\text{constant}\)<br>\(W=\frac{mR(T_1-T_2)}{n-1},\quad n\ne1\)</td><td>Repeated numerical pattern.</td></tr>\012          <tr><td>Dryness fraction</td><td class="pp-formula">\(x=\frac{\text{mass of dry steam}}{\text{total mass of wet steam}}\)</td><td>Steam property questions.</td></tr>\012          <tr><td>Wet steam enthalpy</td><td class="pp-formula">\(h=h_f+xh_{fg}\)</td><td>Steam-table numericals.</td></tr>\012          <tr><td>Wet steam specific volume</td><td class="pp-formula">\(v=v_f+xv_{fg}\approx xv_g\)</td><td>Steam property numericals.</td></tr>\012          <tr><td>Wet steam internal energy</td><td class="pp-formula">\(u=h-Pv\)</td><td>Steam property numericals.</td></tr>\012          <tr><td>Carnot efficiency</td><td class="pp-formula">\(\eta=1-\frac{T_2}{T_1}\)</td><td>Cycle efficiency.</td></tr>\012          <tr><td>Otto cycle efficiency</td><td class="pp-formula">\(\eta=1-\frac{1}{r^{\gamma-1}}\)</td><td>Air-standard efficiency.</td></tr>\012          <tr><td>Diesel cycle efficiency</td><td class="pp-formula">\(\eta=1-\frac{1}{r^{\gamma-1}}\left[\frac{\rho^{\gamma}-1}{\gamma(\rho-1)}\right]\)</td><td>High-value derivation.</td></tr>\012          <tr><td>Brake power</td><td class="pp-formula">\(BP=\frac{2\pi NT}{60}\)</td><td>IC engine performance.</td></tr>\012          <tr><td>Indicated power</td><td class="pp-formula">\(IP=\frac{p_m L A N k}{60}\)</td><td>Engine performance.</td></tr>\012          <tr><td>Mechanical efficiency</td><td class="pp-formula">\(\eta_m=\frac{BP}{IP}\)</td><td>Engine tests.</td></tr>\012          <tr><td>Brake thermal efficiency</td><td class="pp-formula">\(\eta_{bth}=\frac{BP}{\dot m_f\,CV}\)</td><td>Engine numericals.</td></tr>\012          <tr><td>Compressor isothermal work</td><td class="pp-formula">\(W=mRT\ln\left(\frac{P_2}{P_1}\right)\)</td><td>Compressor work.</td></tr>\012          <tr><td>Compressor polytropic work</td><td class="pp-formula">\(W=\frac{n}{n-1}mRT_1\left[\left(\frac{P_2}{P_1}\right)^{\frac{n-1}{n}}-1\right]\)</td><td>Compressor numericals.</td></tr>\012          <tr><td>Coefficient of performance</td><td class="pp-formula">\(COP=\frac{\text{Refrigeration effect}}{\text{Work input}}\)</td><td>Refrigeration.</td></tr>\012          <tr><td>Ton of refrigeration</td><td class="pp-formula">\(1\,TR=210\,\text{kJ/min}=3.5\,\text{kW}\)</td><td>AC capacity numericals.</td></tr>\012          <tr><td>Rankine cycle efficiency</td><td class="pp-formula">\(\eta=\frac{W_{\text{net}}}{Q_{\text{supplied}}}=\frac{W_t-W_p}{Q_s}\)</td><td>Steam plant numerical.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Most Important Laws And Theorems</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Law / Theorem</th><th>Statement</th><th>Where To Use</th></tr></thead>\012        <tbody>\012          <tr><td>Zeroth law of thermodynamics</td><td>If two systems are separately in thermal equilibrium with a third system, they are in thermal equilibrium with each other.</td><td>Temperature measurement and basic thermodynamics.</td></tr>\012          <tr><td>First law of thermodynamics</td><td>Heat supplied to a system equals increase in internal energy plus work done by the system: \(Q=\Delta U+W\).</td><td>All non-flow process numericals.</td></tr>\012          <tr><td>Boyle''''s law</td><td>For a given mass of gas at constant temperature, pressure is inversely proportional to volume: \(PV=\text{constant}\).</td><td>Gas laws.</td></tr>\012          <tr><td>Charles''''s law</td><td>For a given mass of gas at constant pressure, volume is directly proportional to absolute temperature: \(\frac{V}{T}=\text{constant}\).</td><td>Gas laws.</td></tr>\012          <tr><td>Gay-Lussac''''s law</td><td>For a given mass of gas at constant volume, pressure is directly proportional to absolute temperature: \(\frac{P}{T}=\text{constant}\).</td><td>Gas laws.</td></tr>\012          <tr><td>Avogadro''''s law</td><td>Equal volumes of gases at the same temperature and pressure contain equal numbers of molecules.</td><td>Characteristic gas equation.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Most Important Derivations</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Priority</th><th>Derivation</th><th>Must Include</th></tr></thead>\012        <tbody>\012          <tr><td>1</td><td>Characteristic gas equation \(PV=mRT\)</td><td>Boyle''''s law, Charles''''s law and gas constant.</td></tr>\012          <tr><td>2</td><td>Relation \(C_p-C_v=R\)</td><td>Constant pressure heating, constant volume heating and ideal gas relation.</td></tr>\012          <tr><td>3</td><td>Work done for isothermal, adiabatic and polytropic processes.</td><td>Process equation, integration and final formula.</td></tr>\012          <tr><td>4</td><td>Air-standard efficiency of Otto cycle.</td><td>Pressure-volume diagram, compression ratio and \(\gamma\) relation.</td></tr>\012          <tr><td>5</td><td>Air-standard efficiency of Diesel cycle.</td><td>Cut-off ratio, compression ratio and heat addition/rejection.</td></tr>\012          <tr><td>6</td><td>Rankine cycle thermal efficiency.</td><td>\(T-s\) diagram, turbine work, pump work and heat supplied.</td></tr>\012          <tr><td>7</td><td>Brake power and indicated power relations.</td><td>Torque, mean effective pressure and engine cycle notation.</td></tr>\012          <tr><td>8</td><td>Need of multistage compression.</td><td>Pressure-volume diagram and reduction in work input.</td></tr>\012          <tr><td>9</td><td>Coefficient of performance of refrigeration system.</td><td>Refrigeration effect, work input and heat rejection.</td></tr>\012          <tr><td>10</td><td>Steam dryness fraction by throttling calorimeter.</td><td>Throttling enthalpy equality and superheated steam relation.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Most Important Definitions</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Definition</th><th>Exam-Ready Meaning</th></tr></thead>\012        <tbody>\012          <tr><td>Prime mover</td><td>A machine that converts energy from a natural source into mechanical work.</td></tr>\012          <tr><td>Thermodynamic system</td><td>Fixed quantity of matter or region in space selected for study.</td></tr>\012          <tr><td>Open system</td><td>System in which both mass and energy can cross the boundary.</td></tr>\012          <tr><td>Closed system</td><td>System in which energy can cross the boundary but mass cannot.</td></tr>\012          <tr><td>Isolated system</td><td>System in which neither mass nor energy crosses the boundary.</td></tr>\012          <tr><td>Enthalpy</td><td>Total heat content defined as \(H=U+PV\).</td></tr>\012          <tr><td>Dryness fraction</td><td>Mass fraction of dry steam in wet steam.</td></tr>\012          <tr><td>Boiler mounting</td><td>Essential fitting required for safe boiler operation.</td></tr>\012          <tr><td>Boiler accessory</td><td>Device used to improve boiler efficiency or performance.</td></tr>\012          <tr><td>Priming</td><td>Filling a pump casing and suction pipe with liquid before starting.</td></tr>\012          <tr><td>Refrigeration effect</td><td>Heat removed from a low-temperature space.</td></tr>\012          <tr><td>Coefficient of performance</td><td>Ratio of refrigeration effect to work input.</td></tr>\012          <tr><td>Clutch</td><td>Device used to connect or disconnect power transmission while shafts are rotating.</td></tr>\012          <tr><td>Coupling</td><td>Device used to permanently connect two shafts for power transmission.</td></tr>\012          <tr><td>Brake</td><td>Device used to slow down or stop a moving machine element by absorbing energy.</td></tr>\012          <tr><td>Ductility</td><td>Ability of a material to be drawn into wire.</td></tr>\012          <tr><td>Toughness</td><td>Ability of a material to absorb energy before fracture.</td></tr>\012          <tr><td>Hardness</td><td>Resistance of a material to indentation, scratching or wear.</td></tr>\012        </tbody>\012      </table></div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Last-Minute Preparation Strategy</h2>\012      <div class="pp-table-wrap"><table class="pp-table">\012        <thead><tr><th>Time Left</th><th>Do This First</th><th>Avoid This</th></tr></thead>\012        <tbody>\012          <tr><td>Seven days</td><td>Finish Units 2 and 3 numericals and derivations, then boilers, compressors, refrigeration and transmission.</td><td>Decorative note rewriting.</td></tr>\012          <tr><td>Three days</td><td>Write the top fifteen questions once and revise formula sheet, diagrams and comparison tables.</td><td>Starting old-syllabus manufacturing chapters.</td></tr>\012          <tr><td>One day</td><td>Revise gas-process formulas, steam formulas, cycle efficiencies, engine terms, boiler sketches and VCR diagram.</td><td>Full textbook reading.</td></tr>\012          <tr><td>Exam morning</td><td>Only formulas, diagrams, definitions and priority questions.</td><td>Learning new derivations.</td></tr>\012          <tr><td>During exam</td><td>Attempt known questions first, show units and draw large labelled sketches.</td><td>Overwriting one answer while leaving another blank.</td></tr>\012        </tbody>\012      </table></div>\012      <div class="pp-callout"><strong>Final HOD advice:</strong> A full-marks BME answer looks mechanical: labelled sketch, exact formula, correct unit, logical steps and no unnecessary story.</div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Summary</h2>\012      <p>The safest full-marks route in BME is to master Units 2 and 3 first because they carry 42 percent and generate most numericals and derivations. Units 4, 5, 6 and 7 add high-return diagrams and repeated practical questions. Unit 8 is smaller but easy to score through definitions and classification. Old papers are useful only when the topic still matches the latest syllabus.</p>\012      <h3>Golden Rules</h3>\012      <ol class="pp-list">\012        <li>Latest syllabus wins over old-paper habit.</li>\012        <li>Every machine answer needs a neat labelled sketch.</li>\012        <li>Every cycle answer needs a pressure-volume or temperature-entropy diagram.</li>\012        <li>Every numerical must include formula, substitution and unit.</li>\012        <li>Steam-table values must be written clearly.</li>\012        <li>For comparison questions, use a table.</li>\012        <li>Prepare Units 2 and 3 before low-weight topics.</li>\012        <li>Do not ignore boilers, compressors and clutches because they repeat frequently.</li>\012        <li>Keep definitions ready for three-mark questions.</li>\012        <li>Make the examiner''''s job easy: clean structure earns visible marks.</li>\012      </ol>\012    </section>\012\012    <footer class="pp-footer">\012      <p><strong>ShikshaSahayak</strong> &bull; Learn &bull; Prepare &bull; Achieve</p>\012      <div class="pp-links">\012        <a href="https://shikshasahayak.org" target="_blank" rel="noopener noreferrer">Website</a>\012        <a href="https://www.instagram.com/padhaku_portal/" target="_blank" rel="noopener noreferrer">Instagram</a>\012        <a href="https://chat.whatsapp.com/JKjcvjun6roIkbat7O59uJ" target="_blank" rel="noopener noreferrer">WA Community</a>\012        <a href="https://www.whatsapp.com/channel/0029VbCPjEsJf05VIeyIHv2i" target="_blank" rel="noopener noreferrer">WA Channel</a>\012        <a href="https://t.me/padhaku_portal" target="_blank" rel="noopener noreferrer">Telegram</a>\012        <a href="https://www.linkedin.com/company/padhakuportal/" target="_blank" rel="noopener noreferrer">LinkedIn</a>\012      </div>\012      <p style="margin-top:14px;">&copy; 2026 ShikshaSahayak. All Rights Reserved.</p>\012    </footer>\012  </div>\012</div>\012\012<script>\012window.MathJax = {\012  tex: {\012    inlineMath: [[''''\\('''', ''''\\)'''']],\012    displayMath: [[''''\\['''', ''''\\]'''']],\012    processEscapes: true,\012    processEnvironments: true\012  },\012  options: {\012    skipHtmlTags: [''''script'''', ''''noscript'''', ''''style'''', ''''textarea'''', ''''pre'''', ''''code'''']\012  },\012  chtml: {\012    scale: 1.03,\012    mtextInheritFont: false\012  }\012};\012</script>\012<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script>\012</body>\012</html>''',
  '\012',
  'char(10',
  NULL,
