INSERT OR REPLACE INTO blogs (id, related_document_id, title, content, author, category, tags, thumbnail, status, views, created_at, updated_at) VALUES (
  'blog_dd2fd053',
  'doc_21e2d33e',
  'PPS Full Mark Guide By ShikshaSahayak',
  'replace(''<!doctype html>\012<html lang="en">\012<head>\012  <meta charset="utf-8">\012  <meta name="viewport" content="width=device-width, initial-scale=1">\012  <title>PPS Full Marks Preparation Guide | ShikshaSahayak</title>\012</head>\012<body style="margin:0;background:#050812;padding:24px;">\012<!-- ShikshaSahayak PPS Full Mark Guide Blog Post | Blogger Post-Only Code -->\012<style>\012  :root{\012    --pp-bg:#050812;\012    --pp-card:#0b1224;\012    --pp-card2:#101a31;\012    --pp-line:rgba(255,255,255,.10);\012    --pp-text:#eef4ff;\012    --pp-muted:#aab7cf;\012    --pp-orange:#ff8a1f;\012    --pp-orange2:#ffb347;\012    --pp-blue:#5cc8ff;\012    --pp-green:#31d38b;\012    --pp-red:#ff6b6b;\012    --pp-shadow:0 22px 60px rgba(0,0,0,.38);\012  }\012  .pp-blog, .pp-blog *{box-sizing:border-box}\012  .pp-blog{\012    background:\012      radial-gradient(circle at top left, rgba(255,138,31,.20), transparent 32%),\012      radial-gradient(circle at 85% 10%, rgba(92,200,255,.16), transparent 30%),\012      linear-gradient(180deg,#050812 0%,#07101d 45%,#050812 100%);\012    color:var(--pp-text);\012    font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;\012    line-height:1.72;\012    padding:0;\012    margin:0 auto;\012    max-width:1180px;\012    border-radius:24px;\012    overflow:hidden;\012  }\012  .pp-wrap{padding:26px}\012  .pp-hero{\012    position:relative;\012    padding:44px 28px;\012    border:1px solid var(--pp-line);\012    border-radius:28px;\012    background:\012      linear-gradient(135deg,rgba(255,138,31,.17),rgba(92,200,255,.10) 48%,rgba(49,211,139,.08)),\012      linear-gradient(180deg,rgba(16,26,49,.96),rgba(8,15,29,.96));\012    box-shadow:var(--pp-shadow);\012    overflow:hidden;\012  }\012  .pp-hero:before{\012    content:"";\012    position:absolute;\012    inset:auto -80px -120px auto;\012    width:330px;height:330px;\012    background:radial-gradient(circle,rgba(255,138,31,.28),transparent 68%);\012    pointer-events:none;\012  }\012  .pp-badge{\012    display:inline-flex;\012    gap:8px;\012    align-items:center;\012    padding:8px 13px;\012    border:1px solid rgba(255,138,31,.35);\012    color:#ffe0bf;\012    background:rgba(255,138,31,.10);\012    border-radius:999px;\012    font-size:13px;\012    font-weight:800;\012    letter-spacing:.2px;\012    margin-bottom:15px;\012  }\012  .pp-hero h1{\012    margin:0;\012    font-size:clamp(30px,5vw,60px);\012    line-height:1.05;\012    letter-spacing:-1.8px;\012    color:#fff;\012  }\012  .pp-hero h1 span{color:var(--pp-orange2)}\012  .pp-subtitle{\012    max-width:820px;\012    margin:18px 0 0;\012    color:var(--pp-muted);\012    font-size:17px;\012  }\012  .pp-stats{\012    display:grid;\012    grid-template-columns:repeat(4,minmax(0,1fr));\012    gap:14px;\012    margin-top:26px;\012  }\012  .pp-stat{\012    padding:16px;\012    border-radius:18px;\012    background:rgba(255,255,255,.055);\012    border:1px solid var(--pp-line);\012  }\012  .pp-stat b{\012    display:block;\012    font-size:23px;\012    color:#fff;\012    line-height:1.1;\012  }\012  .pp-stat span{\012    display:block;\012    margin-top:6px;\012    color:var(--pp-muted);\012    font-size:13px;\012  }\012  .pp-author-mini{\012    margin-top:22px;\012    display:inline-block;\012    max-width:460px;\012    padding:14px 16px;\012    border-radius:16px;\012    background:rgba(5,8,18,.55);\012    border:1px solid rgba(255,255,255,.12);\012    color:var(--pp-muted);\012    font-size:14px;\012  }\012  .pp-author-mini strong{color:#fff}\012  .pp-section{\012    margin-top:26px;\012    padding:24px;\012    border-radius:24px;\012    background:linear-gradient(180deg,rgba(16,26,49,.96),rgba(10,18,35,.96));\012    border:1px solid var(--pp-line);\012    box-shadow:0 16px 44px rgba(0,0,0,.24);\012  }\012  .pp-section h2{\012    margin:0 0 14px;\012    color:#fff;\012    font-size:clamp(23px,3.2vw,34px);\012    line-height:1.2;\012    letter-spacing:-.7px;\012  }\012  .pp-section h3{\012    margin:22px 0 10px;\012    color:#ffe1c2;\012    font-size:21px;\012  }\012  .pp-section p{color:var(--pp-muted);margin:10px 0}\012  .pp-note{\012    padding:15px 17px;\012    border-left:4px solid var(--pp-orange);\012    background:rgba(255,138,31,.10);\012    border-radius:14px;\012    color:#ffe9d2;\012    margin:16px 0;\012  }\012  .pp-grid{\012    display:grid;\012    grid-template-columns:repeat(2,minmax(0,1fr));\012    gap:16px;\012  }\012  .pp-grid-3{\012    display:grid;\012    grid-template-columns:repeat(3,minmax(0,1fr));\012    gap:16px;\012  }\012  .pp-card{\012    padding:18px;\012    border-radius:18px;\012    background:rgba(255,255,255,.045);\012    border:1px solid var(--pp-line);\012  }\012  .pp-card h3,.pp-card h4{margin-top:0;color:#fff}\012  .pp-card h4{margin-bottom:8px;font-size:17px}\012  .pp-list{margin:10px 0 0;padding-left:20px;color:var(--pp-muted)}\012  .pp-list li{margin:7px 0}\012  .pp-table-wrap{\012    overflow-x:auto;\012    border-radius:18px;\012    border:1px solid var(--pp-line);\012    margin:14px 0 2px;\012  }\012  .pp-table{\012    width:100%;\012    border-collapse:collapse;\012    min-width:720px;\012    background:rgba(255,255,255,.035);\012  }\012  .pp-table th{\012    background:linear-gradient(135deg,rgba(255,138,31,.28),rgba(255,179,71,.18));\012    color:#fff;\012    text-align:left;\012    padding:13px 14px;\012    font-size:14px;\012    border-bottom:1px solid var(--pp-line);\012  }\012  .pp-table td{\012    padding:12px 14px;\012    border-bottom:1px solid rgba(255,255,255,.075);\012    color:var(--pp-muted);\012    vertical-align:top;\012  }\012  .pp-table tr:last-child td{border-bottom:0}\012  .pp-tag{\012    display:inline-block;\012    padding:4px 9px;\012    border-radius:999px;\012    background:rgba(92,200,255,.12);\012    color:#bfefff;\012    border:1px solid rgba(92,200,255,.22);\012    font-size:12px;\012    font-weight:800;\012    white-space:nowrap;\012  }\012  .pp-tag.hot{background:rgba(255,138,31,.13);color:#ffd0a2;border-color:rgba(255,138,31,.28)}\012  .pp-tag.green{background:rgba(49,211,139,.13);color:#c0ffe1;border-color:rgba(49,211,139,.25)}\012  .pp-priority{\012    display:grid;\012    grid-template-columns:repeat(3,minmax(0,1fr));\012    gap:16px;\012  }\012  .pp-priority .pp-card:first-child{border-color:rgba(255,138,31,.35)}\012  .pp-priority .pp-card:nth-child(2){border-color:rgba(92,200,255,.28)}\012  .pp-priority .pp-card:nth-child(3){border-color:rgba(49,211,139,.25)}\012  .pp-code-grid{\012    display:grid;\012    grid-template-columns:repeat(2,minmax(0,1fr));\012    gap:16px;\012  }\012  .pp-code-card{\012    border:1px solid var(--pp-line);\012    border-radius:18px;\012    background:#070b16;\012    overflow:hidden;\012  }\012  .pp-code-title{\012    padding:12px 14px;\012    color:#fff;\012    background:linear-gradient(135deg,rgba(255,138,31,.22),rgba(92,200,255,.10));\012    border-bottom:1px solid var(--pp-line);\012    font-weight:800;\012  }\012  .pp-code-card pre{\012    margin:0;\012    padding:15px;\012    overflow:auto;\012    color:#d9f7ff;\012    font-family:"Fira Code","Consolas","Courier New",monospace;\012    font-size:13px;\012    line-height:1.55;\012    white-space:pre;\012  }\012  .pp-code-card code{font-family:inherit}\012  .pp-footer{\012    margin-top:26px;\012    padding:24px;\012    border-radius:24px;\012    background:linear-gradient(135deg,rgba(255,138,31,.14),rgba(16,26,49,.95));\012    border:1px solid var(--pp-line);\012    text-align:center;\012  }\012  .pp-footer h2{margin-top:0}\012  .pp-links{\012    display:flex;\012    flex-wrap:wrap;\012    justify-content:center;\012    gap:10px;\012    margin:18px 0;\012  }\012  .pp-links a{\012    display:inline-block;\012    text-decoration:none!important;\012    color:#fff!important;\012    background:rgba(255,255,255,.08);\012    border:1px solid rgba(255,255,255,.14);\012    padding:10px 14px;\012    border-radius:999px;\012    font-weight:800;\012    font-size:13px;\012  }\012  .pp-links a:hover{background:rgba(255,138,31,.24)}\012  .pp-small{font-size:13px;color:var(--pp-muted)}\012  @media(max-width:850px){\012    .pp-wrap{padding:15px}\012    .pp-hero{padding:30px 18px}\012    .pp-stats,.pp-grid,.pp-grid-3,.pp-priority,.pp-code-grid{grid-template-columns:1fr}\012    .pp-section{padding:18px}\012  }\012</style>\012\012<div class="pp-blog">\012  <div class="pp-wrap">\012    <section class="pp-hero">\012      <div class="pp-badge">GTU BE | Programming for Problem Solving | Full Mark Guide</div>\012      <h1>PPS Full Marks <span>Preparation Guide</span></h1>\012      <p class="pp-subtitle">\012        A clean exam-focused blog version of the ShikshaSahayak PPS guide: unit-wise strategy,\012        repeated questions, priority topics, important definitions, C programs, formulas, and 24-hour revision plan.\012      </p>\012      <div class="pp-stats">\012        <div class="pp-stat"><b>70</b><span>Theory ESE marks</span></div>\012        <div class="pp-stat"><b>10</b><span>Equal-weight units</span></div>\012        <div class="pp-stat"><b>40%</b><span>Apply-level questions</span></div>\012        <div class="pp-stat"><b>10</b><span>Must-practice C programs</span></div>\012      </div>\012      <div class="pp-author-mini">\012        <strong>Prepared By:</strong><br>\012        <strong>Kishan Takodara</strong><br>\012        Co-Founder, ShikshaSahayak<br>\012        B.E. Information Technology | SSEC, Bhavnagar\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Subject Strategy & Overview</h2>\012      <p>\012        Programming for Problem Solving is not a subject to read only. It is a subject to write, trace,\012        debug and present clearly. Since all units carry equal weightage, the best strategy is to cover\012        every unit at least once and then master the high-frequency programming questions.\012      </p>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Component</th><th>Marks / Credit</th><th>Exam Meaning</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>Theory ESE</td><td>70 marks</td><td>Main written exam. Code writing, definitions, diagrams, comparisons and output tracing matter most.</td></tr>\012            <tr><td>Progressive Assessment</td><td>30 marks</td><td>Internal preparation, assignments, tests and class performance.</td></tr>\012            <tr><td>Tutorial</td><td>20 marks</td><td>Problem practice and written programming logic.</td></tr>\012            <tr><td>Practical</td><td>30 marks</td><td>Execution-based coding and lab understanding.</td></tr>\012            <tr><td>PBL</td><td>30 marks</td><td>Project-based learning and implementation confidence.</td></tr>\012          </tbody>\012        </table>\012      </div>\012\012      <h3>Bloom''''s Taxonomy Distribution</h3>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Level</th><th>Weightage</th><th>How to Prepare</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>Remember</td><td>20%</td><td>Definitions, syntax, symbols, keywords and function names.</td></tr>\012            <tr><td>Understand</td><td>20%</td><td>Explain concepts with examples: compiler, algorithm, pointer, recursion, file.</td></tr>\012            <tr><td>Apply</td><td>40%</td><td>Write C programs, trace output, use loops, functions, arrays, files and memory allocation.</td></tr>\012            <tr><td>Analyze</td><td>20%</td><td>Debug code, compare concepts, identify errors and explain program logic.</td></tr>\012          </tbody>\012        </table>\012      </div>\012      <div class="pp-note"><strong>Important:</strong> All 10 units carry equal weightage. Do not completely skip any unit.</div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Unit-wise Weightage</h2>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Unit</th><th>Topic</th><th>Hours</th><th>Weightage</th><th>Scoring Focus</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>1</td><td>Introduction to Programming</td><td>3</td><td>10%</td><td>Block diagram, algorithm, flowchart, compiler vs interpreter.</td></tr>\012            <tr><td>2</td><td>Basics of C Programming</td><td>3</td><td>10%</td><td>C tokens, data types, operators, precedence and type casting.</td></tr>\012            <tr><td>3</td><td>Control Structures</td><td>3</td><td>10%</td><td>if-else, switch-case, loops, break/continue and pattern programs.</td></tr>\012            <tr><td>4</td><td>Functions & Modular Programming</td><td>3</td><td>10%</td><td>UDF, recursion, call by value/reference and storage classes.</td></tr>\012            <tr><td>5</td><td>Arrays & Strings</td><td>3</td><td>10%</td><td>1D/2D arrays, matrix programs, string functions and searching/sorting.</td></tr>\012            <tr><td>6</td><td>Pointers</td><td>3</td><td>10%</td><td>Pointer declaration, pointer arithmetic, pointer to pointer and array access.</td></tr>\012            <tr><td>7</td><td>Structures & Unions</td><td>3</td><td>10%</td><td>Structure, union, array of structure, nested structure and differences.</td></tr>\012            <tr><td>8</td><td>File Handling</td><td>3</td><td>10%</td><td>File modes, file functions, file copy and random access functions.</td></tr>\012            <tr><td>9</td><td>Dynamic Memory Allocation</td><td>3</td><td>10%</td><td>malloc(), calloc(), realloc(), free() and static vs dynamic allocation.</td></tr>\012            <tr><td>10</td><td>Debugging and Testing</td><td>3</td><td>10%</td><td>Syntax errors, logical errors, output questions, test cases and debugging tools.</td></tr>\012          </tbody>\012        </table>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Full Marks Tips</h2>\012      <div class="pp-grid">\012        <div class="pp-card"><h3>1. Write programs with comments</h3><p>Add 2-3 useful comments, meaningful variable names, proper indentation, sample input and sample output.</p></div>\012        <div class="pp-card"><h3>2. Use diagrams for theory</h3><p>For block diagrams and flowcharts, draw neat labeled diagrams. Even short answers become stronger with visuals.</p></div>\012        <div class="pp-card"><h3>3. Master 7-mark programs</h3><p>Practice factorial recursion, prime using UDF, matrix operations, string functions, file copy and pattern printing.</p></div>\012        <div class="pp-card"><h3>4. Follow explain + example + output</h3><p>For 4-mark and 7-mark questions, first explain the concept, then write code or diagram, then show output/result.</p></div>\012        <div class="pp-card"><h3>5. Use tables for differences</h3><p>Compiler vs interpreter, while vs do-while, structure vs union, malloc vs calloc and call by value vs reference are best written in table form.</p></div>\012        <div class="pp-card"><h3>6. Attempt everything</h3><p>If exact code is not remembered, write algorithm, logic, partial syntax or related definition. Partial marking can save marks.</p></div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Chapter-wise Important Topics</h2>\012      <div class="pp-grid">\012        <div class="pp-card"><h3>Unit 1: Introduction</h3><ul class="pp-list"><li>Block diagram of computer system</li><li>Compiler vs interpreter</li><li>Algorithm definition, steps and examples</li><li>Flowchart symbols and examples</li><li>System software vs application software</li></ul></div>\012        <div class="pp-card"><h3>Unit 2: Basics of C</h3><ul class="pp-list"><li>Structure of a C program</li><li>C tokens: keywords, identifiers, constants, strings and operators</li><li>Data types and size/range</li><li>Operator precedence and associativity</li><li>Implicit and explicit type casting</li></ul></div>\012        <div class="pp-card"><h3>Unit 3: Control Structures</h3><ul class="pp-list"><li>if, if-else, nested if-else and else-if ladder</li><li>switch-case with menu-driven program</li><li>for, while and do-while loops</li><li>break and continue</li><li>Star and number pattern programs</li></ul></div>\012        <div class="pp-card"><h3>Unit 4: Functions</h3><ul class="pp-list"><li>Function declaration, definition and call</li><li>Call by value vs call by reference</li><li>Recursion: factorial, Fibonacci and sum of digits</li><li>Categories of user-defined functions</li><li>Storage classes: auto, extern, static, register</li></ul></div>\012        <div class="pp-card"><h3>Unit 5: Arrays & Strings</h3><ul class="pp-list"><li>1D and 2D arrays</li><li>Matrix addition, multiplication and transpose</li><li>Bubble sort and selection sort</li><li>String functions: strlen(), strcpy(), strcat(), strcmp()</li><li>Linear and binary search</li></ul></div>\012        <div class="pp-card"><h3>Unit 6: Pointers</h3><ul class="pp-list"><li>Pointer declaration and initialization</li><li>Pointer arithmetic</li><li>Pointer to pointer</li><li>Array access using pointers</li><li>Pointers to functions</li></ul></div>\012        <div class="pp-card"><h3>Unit 7: Structures & Unions</h3><ul class="pp-list"><li>Structure declaration, initialization and member access</li><li>Array of structures</li><li>Nested structures</li><li>Pointer to structure</li><li>Structure vs union comparison</li></ul></div>\012        <div class="pp-card"><h3>Unit 8: File Handling</h3><ul class="pp-list"><li>Opening, closing, reading and writing files</li><li>File modes: r, w, a, r+, w+, a+</li><li>fopen(), fclose(), fscanf(), fprintf(), fread(), fwrite()</li><li>fseek(), ftell(), rewind()</li><li>File copy program</li></ul></div>\012        <div class="pp-card"><h3>Unit 9: DMA</h3><ul class="pp-list"><li>Static vs dynamic memory allocation</li><li>malloc(), calloc(), realloc() and free()</li><li>malloc vs calloc</li><li>Memory allocation failure check</li><li>Heap memory concept</li></ul></div>\012        <div class="pp-card"><h3>Unit 10: Debugging</h3><ul class="pp-list"><li>Syntax errors and logical errors</li><li>Debugging techniques and tools</li><li>Output-based code snippets</li><li>Identifying and fixing code errors</li><li>Writing test cases</li></ul></div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Chapter-wise Repeated Questions</h2>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Unit</th><th>Repeated / Important Question</th><th>Marks</th><th>Priority</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>1</td><td>Draw block diagram of computer and explain functions of each component.</td><td>7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>1</td><td>Define compiler, interpreter and algorithm. Differentiate compiler and interpreter.</td><td>3-4</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>1</td><td>Design flowchart for palindrome, factorial or maximum of three numbers.</td><td>4-7</td><td><span class="pp-tag hot">High</span></td></tr>\012            <tr><td>2</td><td>Explain C tokens, data types, operators, precedence and associativity.</td><td>4-7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>2</td><td>Explain bitwise operators, type casting and ternary operator with examples.</td><td>3-7</td><td><span class="pp-tag">High</span></td></tr>\012            <tr><td>3</td><td>Pattern printing programs using loops.</td><td>7</td><td><span class="pp-tag hot">Most Repeated</span></td></tr>\012            <tr><td>3</td><td>Explain switch-case, while vs do-while, break vs continue.</td><td>3-7</td><td><span class="pp-tag">High</span></td></tr>\012            <tr><td>4</td><td>Write recursive program for factorial or Fibonacci series.</td><td>7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>4</td><td>Differentiate call by value and call by reference.</td><td>3-7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>4</td><td>Write a user-defined function to check prime number.</td><td>7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>5</td><td>Explain string functions strlen(), strcpy(), strcat(), strcmp().</td><td>7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>5</td><td>Matrix multiplication, array sorting, max/min from array and string copy without library function.</td><td>7</td><td><span class="pp-tag">High</span></td></tr>\012            <tr><td>7</td><td>Structure vs union; student record program using structure.</td><td>3-7</td><td><span class="pp-tag">High</span></td></tr>\012            <tr><td>8</td><td>File handling functions, file modes, file copy program, fseek(), ftell(), rewind().</td><td>4-7</td><td><span class="pp-tag">High</span></td></tr>\012            <tr><td>9</td><td>Compare malloc() and calloc(); explain dynamic memory allocation functions.</td><td>3-7</td><td><span class="pp-tag hot">Very High</span></td></tr>\012            <tr><td>10</td><td>Output-based questions and identify syntax/logical errors.</td><td>3-4</td><td><span class="pp-tag">High</span></td></tr>\012          </tbody>\012        </table>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Combined Priority Question List</h2>\012      <div class="pp-priority">\012        <div class="pp-card">\012          <h3>Priority 1 - Must Do</h3>\012          <ul class="pp-list">\012            <li>Block diagram of computer system</li>\012            <li>Factorial using recursion</li>\012            <li>Call by value vs call by reference</li>\012            <li>Prime number using UDF</li>\012            <li>String handling functions</li>\012            <li>Pattern printing programs</li>\012            <li>Fibonacci series using recursion</li>\012            <li>Operators with precedence and associativity</li>\012            <li>Structure vs union</li>\012            <li>malloc() vs calloc()</li>\012            <li>File copy program</li>\012            <li>Switch-case menu-driven program</li>\012          </ul>\012        </div>\012        <div class="pp-card">\012          <h3>Priority 2 - Should Do</h3>\012          <ul class="pp-list">\012            <li>Algorithm and flowchart examples</li>\012            <li>Compiler vs interpreter</li>\012            <li>C tokens and data types</li>\012            <li>Bitwise operators</li>\012            <li>Else-if ladder, break and continue</li>\012            <li>while vs do-while loop</li>\012            <li>Storage classes</li>\012            <li>1D and 2D arrays</li>\012            <li>Matrix multiplication</li>\012            <li>Student record using structure</li>\012            <li>File modes and random access functions</li>\012            <li>Dynamic memory allocation functions</li>\012          </ul>\012        </div>\012        <div class="pp-card">\012          <h3>Priority 3 - Good to Know</h3>\012          <ul class="pp-list">\012            <li>Types of programming languages</li>\012            <li>Types of software</li>\012            <li>Header files and usage</li>\012            <li>goto statement and why to avoid it</li>\012            <li>Function vs macro</li>\012            <li>Pointer declaration and advantages</li>\012            <li>Pointer to pointer</li>\012            <li>Union definition and example</li>\012            <li>Error handling in files</li>\012            <li>Basic debugging tools</li>\012          </ul>\012        </div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Skip List - Only If Time Is Very Short</h2>\012      <div class="pp-note">\012        “Skip” means low probability from past paper trends, not zero importance. Read these topics once if time allows.\012      </div>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Unit</th><th>Topic</th><th>Reason</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>1</td><td>Generations / detailed history of computers</td><td>Not a core repeated GTU PPS question.</td></tr>\012            <tr><td>2</td><td>Detailed ASCII/EBCDIC tables</td><td>Rarely asked directly.</td></tr>\012            <tr><td>3</td><td>Comma / sizeof operator as standalone theory</td><td>Low standalone probability.</td></tr>\012            <tr><td>4</td><td>Function pointers</td><td>Low probability in current pattern.</td></tr>\012            <tr><td>5</td><td>3D/4D arrays</td><td>2D arrays are more important.</td></tr>\012            <tr><td>7</td><td>Bit fields in structures</td><td>Very rarely asked.</td></tr>\012            <tr><td>8</td><td>fputw(), fgetw()</td><td>Low probability compared to fopen(), fgetc(), fputc(), fprintf(), fscanf().</td></tr>\012            <tr><td>9</td><td>Memory leak detection tools</td><td>Not commonly asked in GTU papers.</td></tr>\012            <tr><td>10</td><td>Advanced gdb commands</td><td>Focus on basic debugging concepts first.</td></tr>\012          </tbody>\012        </table>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Important Formulas, Syntax & Expressions</h2>\012      <div class="pp-grid">\012        <div class="pp-card">\012          <h3>Operator Quick Table</h3>\012          <div class="pp-table-wrap">\012            <table class="pp-table">\012              <thead><tr><th>Type</th><th>Operators</th><th>Example</th></tr></thead>\012              <tbody>\012                <tr><td>Arithmetic</td><td><code>+ - * / %</code></td><td><code>a + b</code>, <code>a % b</code></td></tr>\012                <tr><td>Relational</td><td><code>&lt; &gt; &lt;= &gt;= == !=</code></td><td><code>if (a &gt; b)</code></td></tr>\012                <tr><td>Logical</td><td><code>&amp;&amp; || !</code></td><td><code>if (a &gt; 0 &amp;&amp; b &gt; 0)</code></td></tr>\012                <tr><td>Bitwise</td><td><code>&amp; | ^ ~ &lt;&lt; &gt;&gt;</code></td><td><code>a &lt;&lt; 2</code></td></tr>\012                <tr><td>Assignment</td><td><code>= += -= *= /= %=</code></td><td><code>a += 5</code></td></tr>\012                <tr><td>Ternary</td><td><code>? :</code></td><td><code>max = (a &gt; b) ? a : b;</code></td></tr>\012              </tbody>\012            </table>\012          </div>\012        </div>\012        <div class="pp-card">\012          <h3>Expression Rules</h3>\012          <ul class="pp-list">\012            <li>Modulus gives remainder: \(10 \bmod 3 = 1\)</li>\012            <li>Arithmetic precedence: \(5+3\times2=11\), not 16.</li>\012            <li>Temperature conversion: \(F=(C\times 9/5)+32\)</li>\012            <li>Temperature conversion: \(C=(F-32)\times 5/9\)</li>\012            <li>General precedence idea: unary, arithmetic, relational, logical AND, logical OR, assignment.</li>\012          </ul>\012        </div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Important Definitions - Complete PDF Bank</h2>\012      <div class="pp-grid">\012        <div class="pp-card"><h3>Algorithm</h3><p>A step-by-step procedure to solve a problem. It must be unambiguous, finite, feasible, and independent of programming language.</p></div>\012        <div class="pp-card"><h3>Flowchart</h3><p>A graphical representation of an algorithm using standard symbols. Common symbols are oval for start/end, parallelogram for input/output, rectangle for process, diamond for decision, and arrow for flow.</p></div>\012        <div class="pp-card"><h3>Compiler</h3><p>A language translator that converts the entire source code into machine code at once. It detects all errors together and gives faster execution. Examples: GCC, Turbo C.</p></div>\012        <div class="pp-card"><h3>Interpreter</h3><p>A language translator that converts source code line-by-line. It stops at the first error. It is slower in execution but easier for debugging. Examples: Python interpreter, BASIC.</p></div>\012        <div class="pp-card"><h3>C Token</h3><p>The smallest individual unit in a C program. Types include keywords, identifiers, constants, strings, operators, and special symbols.</p></div>\012        <div class="pp-card"><h3>Identifier</h3><p>Names given to variables, functions, arrays, etc. Rules: it must start with a letter or underscore, can contain letters, digits and underscore, is case-sensitive, and keywords are not allowed.</p></div>\012        <div class="pp-card"><h3>Constant</h3><p>A fixed value that does not change during program execution. Types include integer, real/float, character, string, and enumeration constants.</p></div>\012        <div class="pp-card"><h3>Recursion</h3><p>A function calling itself directly or indirectly. It must have a base condition to stop termination. Example: \(factorial(n)=n\times factorial(n-1)\).</p></div>\012        <div class="pp-card"><h3>Pointer</h3><p>A variable that stores the memory address of another variable. Declaration: <code>int *ptr;</code> Initialization: <code>ptr = &amp;a;</code> Size of pointer depends on architecture, commonly 4 bytes on 32-bit systems and 8 bytes on 64-bit systems.</p></div>\012        <div class="pp-card"><h3>Structure</h3><p>A user-defined data type that groups variables of different data types under one name. Keyword: <code>struct</code>. Members can be accessed using the dot <code>.</code> operator.</p></div>\012        <div class="pp-card"><h3>Union</h3><p>A user-defined data type similar to structure, but all members share the same memory location. Size of a union is equal to the size of its largest member. Only one member can store a value at a time.</p></div>\012        <div class="pp-card"><h3>Dynamic Memory Allocation</h3><p>Allocating memory at runtime during program execution. Functions: <code>malloc()</code>, <code>calloc()</code>, <code>realloc()</code>, and <code>free()</code>. Memory is allocated on the heap.</p></div>\012        <div class="pp-card"><h3>File</h3><p>A named location on secondary storage used to store data persistently. Operations include create, open, read, write, and close. Common modes are <code>r</code>, <code>w</code>, <code>a</code>, <code>r+</code>, <code>w+</code>, and <code>a+</code>.</p></div>\012        <div class="pp-card"><h3>Debugging</h3><p>The process of identifying and removing errors or bugs from a program. Common errors include syntax errors, logical errors, and runtime errors.</p></div>\012        <div class="pp-card"><h3>Function</h3><p>A self-contained block of code that performs a specific task. Benefits include reusability, modularity, and easier debugging. Types include library functions and user-defined functions.</p></div>\012        <div class="pp-card"><h3>Array</h3><p>A collection of elements of the same data type stored in contiguous memory locations. Index starts from 0. Size must be specified at declaration for static arrays.</p></div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Top 10 Most Important C Programs</h2>\012      <div class="pp-code-grid">\012        <div class="pp-code-card">\012          <div class="pp-code-title">1. Factorial Using Recursion</div>\012<pre><code>int fact(int n) {\012    if (n &lt;= 1)\012        return 1;\012    return n * fact(n - 1);\012}\012\012void main() {\012    int n = 5;\012    printf("Factorial of %d = %d", n, fact(n));\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">2. Fibonacci Series Using Recursion</div>\012<pre><code>int fib(int n) {\012    if (n &lt;= 1)\012        return n;\012    return fib(n - 1) + fib(n - 2);\012}\012\012void main() {\012    int n = 10, i;\012    for (i = 0; i &lt; n; i++)\012        printf("%d ", fib(i));\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">3. Check Prime Number Using UDF</div>\012<pre><code>int isPrime(int n) {\012    int i;\012    if (n &lt;= 1)\012        return 0;\012    for (i = 2; i &lt;= n / 2; i++) {\012        if (n % i == 0)\012            return 0;\012    }\012    return 1;\012}\012\012void main() {\012    int n = 17;\012    if (isPrime(n))\012        printf("Prime");\012    else\012        printf("Not Prime");\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">4. Menu-Driven Calculator</div>\012<pre><code>void main() {\012    int a, b, ch;\012    printf("1.Add 2.Sub 3.Mul 4.Div\nEnter choice: ");\012    scanf("%d", &amp;ch);\012    printf("Enter two numbers: ");\012    scanf("%d%d", &amp;a, &amp;b);\012\012    switch (ch) {\012        case 1: printf("Sum = %d", a + b); break;\012        case 2: printf("Diff = %d", a - b); break;\012        case 3: printf("Prod = %d", a * b); break;\012        case 4: printf("Div = %.2f", (float)a / b); break;\012        default: printf("Invalid");\012    }\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">5. Bubble Sort</div>\012<pre><code>void main() {\012    int arr[100], n, i, j, temp;\012    printf("Enter n: ");\012    scanf("%d", &amp;n);\012\012    for (i = 0; i &lt; n; i++)\012        scanf("%d", &amp;arr[i]);\012\012    for (i = 0; i &lt; n - 1; i++) {\012        for (j = 0; j &lt; n - i - 1; j++) {\012            if (arr[j] &gt; arr[j + 1]) {\012                temp = arr[j];\012                arr[j] = arr[j + 1];\012                arr[j + 1] = temp;\012            }\012        }\012    }\012\012    for (i = 0; i &lt; n; i++)\012        printf("%d ", arr[i]);\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">6. String Comparison Without Library Function</div>\012<pre><code>void main() {\012    char s1[100], s2[100];\012    int i, flag = 0;\012\012    gets(s1);\012    gets(s2);\012\012    for (i = 0; s1[i] != ''''\0'''' || s2[i] != ''''\0''''; i++) {\012        if (s1[i] != s2[i]) {\012            flag = 1;\012            break;\012        }\012    }\012\012    if (flag == 0)\012        printf("Strings are equal");\012    else\012        printf("Strings are not equal");\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">7. Student Record Using Structure</div>\012<pre><code>struct Student {\012    int roll;\012    char name[50];\012    float marks;\012};\012\012void main() {\012    struct Student s[3];\012    int i;\012\012    for (i = 0; i &lt; 3; i++) {\012        printf("Enter roll, name, marks: ");\012        scanf("%d %s %f", &amp;s[i].roll, s[i].name, &amp;s[i].marks);\012    }\012\012    for (i = 0; i &lt; 3; i++)\012        printf("%d %s %.2f\n", s[i].roll, s[i].name, s[i].marks);\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">8. File Copy Program</div>\012<pre><code>void main() {\012    FILE *f1, *f2;\012    char ch;\012\012    f1 = fopen("source.txt", "r");\012    f2 = fopen("dest.txt", "w");\012\012    if (f1 == NULL || f2 == NULL) {\012        printf("File error!");\012        return;\012    }\012\012    while ((ch = fgetc(f1)) != EOF)\012        fputc(ch, f2);\012\012    printf("File copied successfully!");\012    fclose(f1);\012    fclose(f2);\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">9. Dynamic Memory Allocation</div>\012<pre><code>void main() {\012    int n, *arr, i;\012    printf("Enter number of elements: ");\012    scanf("%d", &amp;n);\012\012    arr = (int*) malloc(n * sizeof(int));\012    if (arr == NULL) {\012        printf("Memory allocation failed!");\012        return;\012    }\012\012    for (i = 0; i &lt; n; i++)\012        scanf("%d", &amp;arr[i]);\012\012    for (i = 0; i &lt; n; i++)\012        printf("%d ", arr[i]);\012\012    free(arr);\012}</code></pre>\012        </div>\012        <div class="pp-code-card">\012          <div class="pp-code-title">10. Matrix Addition</div>\012<pre><code>void main() {\012    int a[2][2], b[2][2], c[2][2], i, j;\012\012    for (i = 0; i &lt; 2; i++)\012        for (j = 0; j &lt; 2; j++)\012            scanf("%d", &amp;a[i][j]);\012\012    for (i = 0; i &lt; 2; i++)\012        for (j = 0; j &lt; 2; j++)\012            scanf("%d", &amp;b[i][j]);\012\012    for (i = 0; i &lt; 2; i++)\012        for (j = 0; j &lt; 2; j++)\012            c[i][j] = a[i][j] + b[i][j];\012\012    for (i = 0; i &lt; 2; i++) {\012        for (j = 0; j &lt; 2; j++)\012            printf("%d ", c[i][j]);\012        printf("\n");\012    }\012}</code></pre>\012        </div>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>24-Hour Last Minute Strategy</h2>\012      <div class="pp-table-wrap">\012        <table class="pp-table">\012          <thead>\012            <tr><th>Phase</th><th>Time</th><th>What to Do</th></tr>\012          </thead>\012          <tbody>\012            <tr><td>Phase 1</td><td>8 hours</td><td>Revise all Priority 1 topics and write the top 10 programs by hand.</td></tr>\012            <tr><td>Phase 2</td><td>4 hours</td><td>Quickly scan Priority 2 topics: algorithms, flowcharts, operators, data types, loops and patterns.</td></tr>\012            <tr><td>Phase 3</td><td>3 hours</td><td>Revise definitions, operator table, syntax and expression evaluation.</td></tr>\012            <tr><td>Phase 4</td><td>3 hours</td><td>Solve one previous paper with timing and proper answer-sheet presentation.</td></tr>\012            <tr><td>Phase 5</td><td>2 hours</td><td>Night-before revision: all unit headings, formulas, common differences and program logic.</td></tr>\012            <tr><td>Phase 6</td><td>1 hour</td><td>Exam morning: revise golden rules, reach early and carry pencil for diagrams/flowcharts.</td></tr>\012          </tbody>\012        </table>\012      </div>\012    </section>\012\012    <section class="pp-section">\012      <h2>Exam Hall Golden Rules</h2>\012      <div class="pp-grid-3">\012        <div class="pp-card"><h3>Program answers</h3><p>Write heading, algorithm/logic, C code with indentation and output. Use comments where useful.</p></div>\012        <div class="pp-card"><h3>Theory answers</h3><p>Use definition, explanation, diagram/example and final point. Underline keywords neatly.</p></div>\012        <div class="pp-card"><h3>Comparison answers</h3><p>Always use a table. Tables are faster to check and look more complete.</p></div>\012      </div>\012    </section>\012\012    <footer class="pp-footer">\012      <h2>Learn. Prepare. Achieve.</h2>\012      <p>Stay connected with ShikshaSahayak for exam-focused guides, PYQs, notes and smart revision support.</p>\012      <div class="pp-links">\012        <a href="https://shikshasahayak.org" target="_blank" rel="noopener">Website</a>\012        <a href="https://www.instagram.com/padhaku_portal/" target="_blank" rel="noopener">Instagram</a>\012        <a href="https://chat.whatsapp.com/JKjcvjun6roIkbat7O59uJ" target="_blank" rel="noopener">WA Community</a>\012        <a href="https://www.whatsapp.com/channel/0029VbCPjEsJf05VIeyIHv2i" target="_blank" rel="noopener">WA Channel</a>\012        <a href="https://t.me/padhaku_portal" target="_blank" rel="noopener">Telegram</a>\012        <a href="https://www.linkedin.com/company/padhakuportal/" target="_blank" rel="noopener">LinkedIn</a>\012      </div>\012      <p class="pp-small">© 2026 ShikshaSahayak. All Rights Reserved.</p>\012    </footer>\012  </div>\012</div>\012\012<script>\012window.MathJax = {\012  tex: {\012    inlineMath: [[''''\\('''', ''''\\)'''']],\012    displayMath: [[''''\\['''', ''''\\]'''']],\012    processEscapes: true,\012    processEnvironments: true\012  },\012  options: {\012    skipHtmlTags: [''''script'''', ''''noscript'''', ''''style'''', ''''textarea'''', ''''pre'''', ''''code'''']\012  },\012  chtml: {\012    scale: 1.03,\012    mtextInheritFont: false\012  }\012};\012</script>\012<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script>\012\012</body>\012</html>''',
  '\012',
  'char(10',
  NULL,
