INSERT OR REPLACE INTO blogs (id, related_document_id, title, content, author, category, tags, thumbnail, status, views, created_at, updated_at) VALUES (
  'blog_7c0f9fdb',
  'doc_9131110f',
  'ISS Full Mark Guide by ShikshaSahayak',
  'replace(''<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>ISS Full Marks Guide | ShikshaSahayak</title>\n</head>\n<body style="margin:0;background:#050814">\n\n\n<style>\n:root{\n  --pp-bg:#050814;\n  --pp-panel:#101827;\n  --pp-panel2:#121d31;\n  --pp-soft:#1a2940;\n  --pp-line:#26364f;\n  --pp-text:#eef4ff;\n  --pp-muted:#a9b6c9;\n  --pp-orange:#ff7a1a;\n  --pp-yellow:#ffd166;\n  --pp-blue:#5ab0ff;\n  --pp-green:#62d6a2;\n  --pp-red:#ff6b6b;\n}\n.pp-blog *{box-sizing:border-box}\n.pp-blog{background:radial-gradient(circle at top left,rgba(255,122,26,.16),transparent 32%),linear-gradient(180deg,#050814 0%,#090d1b 55%,#050814 100%);color:var(--pp-text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;line-height:1.65;padding:0;margin:0;border-radius:24px;overflow:hidden}\n.pp-shell{max-width:1120px;margin:0 auto;padding:28px 18px 42px}\n.pp-hero{border:1px solid rgba(255,255,255,.12);background:linear-gradient(135deg,rgba(16,24,39,.95),rgba(10,15,30,.96));border-radius:28px;padding:34px 26px;margin:8px 0 26px;position:relative;overflow:hidden;box-shadow:0 18px 55px rgba(0,0,0,.35)}\n.pp-hero:before{content:"";position:absolute;width:280px;height:280px;border-radius:999px;background:rgba(255,122,26,.18);right:-120px;top:-120px}.pp-hero:after{content:"";position:absolute;width:260px;height:260px;border-radius:999px;background:rgba(90,176,255,.12);left:-120px;bottom:-140px}\n.pp-badge{display:inline-flex;align-items:center;gap:8px;color:#fff;background:rgba(255,122,26,.14);border:1px solid rgba(255,122,26,.55);border-radius:999px;padding:7px 13px;font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;position:relative;z-index:1}\n.pp-hero h1{font-size:clamp(30px,5vw,58px);line-height:1.04;margin:18px 0 10px;letter-spacing:-.04em;position:relative;z-index:1}.pp-hero h1 span{color:var(--pp-orange)}\n.pp-sub{font-size:clamp(16px,2vw,21px);color:var(--pp-muted);max-width:790px;position:relative;z-index:1}.pp-meta-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:24px;position:relative;z-index:1}.pp-meta{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:14px}.pp-meta small{display:block;color:var(--pp-muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}.pp-meta b{display:block;margin-top:5px;color:#fff;font-size:15px}\n.pp-section{background:rgba(16,24,39,.9);border:1px solid rgba(255,255,255,.1);border-radius:24px;padding:24px;margin:22px 0;box-shadow:0 10px 35px rgba(0,0,0,.22)}\n.pp-section h2{font-size:clamp(24px,3vw,34px);line-height:1.15;margin:0 0 16px;color:#fff;letter-spacing:-.03em}.pp-section h3{font-size:21px;margin:24px 0 10px;color:var(--pp-orange)}.pp-section h4{font-size:18px;margin:20px 0 8px;color:var(--pp-yellow)}\n.pp-lead{font-size:17px;color:var(--pp-muted);margin:0 0 12px}.pp-note,.pp-warning,.pp-tip{border-radius:18px;padding:16px 18px;margin:16px 0;border:1px solid}.pp-note{background:rgba(90,176,255,.08);border-color:rgba(90,176,255,.28)}.pp-warning{background:rgba(255,107,107,.08);border-color:rgba(255,107,107,.32)}.pp-tip{background:rgba(98,214,162,.08);border-color:rgba(98,214,162,.32)}\n.pp-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pp-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.pp-card{background:linear-gradient(180deg,rgba(26,41,64,.95),rgba(12,18,32,.95));border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:18px}.pp-card b{color:#fff}.pp-card .tag{display:inline-block;background:rgba(255,122,26,.15);color:var(--pp-orange);border:1px solid rgba(255,122,26,.35);border-radius:999px;padding:4px 9px;font-size:12px;font-weight:800;margin-bottom:8px}\nul,ol{padding-left:22px;margin:9px 0}li{margin:7px 0}.pp-highlight{color:var(--pp-orange);font-weight:800}.pp-muted{color:var(--pp-muted)}\n.pp-table-wrap{width:100%;overflow-x:auto;margin:15px 0;border-radius:16px;border:1px solid rgba(255,255,255,.12)}.pp-table{width:100%;border-collapse:collapse;min-width:720px;background:#0d1424}.pp-table th{background:#182338;color:#fff;text-align:left;font-weight:800}.pp-table th,.pp-table td{padding:12px 14px;border-bottom:1px solid rgba(255,255,255,.09);vertical-align:top}.pp-table td{color:#dce7f7}.pp-table tr:nth-child(even) td{background:rgba(255,255,255,.025)}.pp-table .priority{font-weight:800;color:var(--pp-yellow)}\n.pp-formula{font-size:16px}.pp-author{display:flex;gap:18px;align-items:center;background:linear-gradient(135deg,rgba(255,122,26,.1),rgba(90,176,255,.08));border:1px solid rgba(255,255,255,.12);border-radius:22px;padding:18px;margin-top:14px}.pp-avatar{width:60px;height:60px;border-radius:18px;background:linear-gradient(135deg,var(--pp-orange),#ffb15f);display:grid;place-items:center;font-size:26px;font-weight:900;color:#07111f;flex:none}.pp-footer{border-top:1px solid rgba(255,255,255,.12);padding:24px 0 0;margin-top:26px;text-align:center}.pp-links{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}.pp-links a{display:inline-flex;text-decoration:none;color:#fff;background:#111c2f;border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:10px 14px;font-weight:800}.pp-links a:hover{background:#ff7a1a;color:#08111f}.pp-footnote{color:var(--pp-muted);font-size:13px;margin-top:16px}\n@media(max-width:850px){.pp-meta-grid,.pp-grid,.pp-cards{grid-template-columns:1fr}.pp-hero{padding:26px 18px}.pp-section{padding:20px 16px}.pp-shell{padding:16px 10px 30px}.pp-table{min-width:640px}.pp-author{align-items:flex-start}.pp-avatar{width:52px;height:52px}}\n</style>\n\n<div class="pp-blog">\n  <div class="pp-shell">\n    <section class="pp-hero">\n      <div class="pp-badge">ShikshaSahayak | GTU BE Semester 2</div>\n      <h1>Industrial Safety and Standards <span>Full Marks Guide</span></h1>\n      <p class="pp-sub">A professional, student-friendly blog version of the ISS Full Marks Exam Preparation Report for GTU BE Semester 2.</p>\n      <div class="pp-meta-grid">\n        <div class="pp-meta"><small>Subject Code</small><b>BE02R00061 / BE02000061</b></div>\n        <div class="pp-meta"><small>Syllabus Used</small><b>Latest GTU syllabus, WEF 2024-25 / 2025-26</b></div>\n        <div class="pp-meta"><small>Exam Focus</small><b>End Semester Examination, 70 marks</b></div>\n        <div class="pp-meta"><small>Prepared by</small><b>Ayush Pandey</b></div>\n      </div>\n      <div class="pp-note" style="position:relative;z-index:1;margin-top:22px"><b>Design note:</b> This blog is intentionally simple, minimal and student-friendly, prepared in a digital handwritten-notes inspired style for quick revision.</div>\n    </section>\n    \n<section class="pp-section">\n  <h2>About ShikshaSahayak</h2>\n  <div class="pp-note"><b>Student-first academic support</b><br>ShikshaSahayak is a student-focused educational website created to help engineering students find previous year question papers, study notes, revision guides, and practical exam preparation support in one organized place.</div>\n  <h3>Our Purpose</h3>\n  <p>Students often lose time searching scattered drives, chats, and unofficial folders before every exam. ShikshaSahayak brings commonly needed academic resources into a clearer structure by branch, semester, subject, and resource type. The goal is simple: make preparation easier without encouraging shortcuts, plagiarism, or blind dependence on repeated questions.</p>\n  <div class="pp-table-wrap"><table class="pp-table "><thead><tr><th>Resource</th><th>How It Helps Students</th></tr></thead><tbody><tr><td>Previous year papers</td><td>PYQs organized with filters for department, semester, year, and paper type.</td></tr><tr><td>Study notes</td><td>Submitted notes and summaries that are reviewed before public listing.</td></tr><tr><td>Study guides</td><td>Original guides on subjects, PYQ strategy, answer writing, lab work, and revision planning.</td></tr><tr><td>AI Tutor</td><td>Academic support for explanations, practice prompts, and concept revision. AI answers should be verified before use.</td></tr><tr><td>Contribution flow</td><td>A way for students to submit useful material for admin review.</td></tr></tbody></table></div>\n  <h3>Editorial and Review Approach</h3>\n  <p>Public study guides are written for clarity, usefulness, and student safety. Contributed notes and papers are reviewed by admins before publication. We aim to remove low-quality uploads, copyrighted material that should not be shared, misleading claims, and resources that do not match the educational purpose of the site.</p>\n  <div class="pp-warning"><b>Official-use disclaimer:</b> ShikshaSahayak is not an official university website and does not claim endorsement by any college, university, exam board, or government body. Students should cross-check important academic details with their official syllabus, faculty instructions, and university notices.</div>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Copyright, Intellectual Property &amp; Legal Notice</h2>\n  <p><b>&copy; 2026 ShikshaSahayak. All Rights Reserved.</b></p>\n  <ul><li><b>Ownership:</b> This publication, including its content, design, formatting, question-bank structure, exam analysis, study strategy, branding, and associated material, is the intellectual property of ShikshaSahayak and its respective author.</li><li><b>Permission:</b> No part of this publication may be copied, reproduced, redistributed, republished, sold, uploaded, transmitted, stored, modified, translated, or shared in any form without prior written permission from ShikshaSahayak.</li><li><b>Educational Purpose:</b> This material is intended solely for educational and academic support. It is designed to help students prepare responsibly, revise efficiently, and understand paper patterns without promoting shortcuts or unfair practices.</li><li><b>Accuracy Reminder:</b> Reasonable efforts have been made to keep the analysis aligned with the latest syllabus and supplied references. Students must still verify important academic details with official GTU notices, faculty instructions, and the official syllabus.</li><li><b>Question Sources:</b> Questions and trends discussed in this publication may be compiled from university examinations, official syllabi, textbooks, and independent academic analysis. Their inclusion is only for study and examination preparation.</li><li><b>No Guarantee:</b> Predictions, priority lists, and repeated-question observations are guidance based on academic analysis and historical patterns. They are not guarantees of examination content, marks, or results.</li><li><b>Permitted Usage:</b> Students may download, print, annotate, and use this publication for personal, non-commercial academic preparation.</li><li><b>Prohibited Usage:</b> Redistribution, resale, website uploads, coaching-material reproduction, commercial use, content scraping, AI-training dataset use, or creation of derivative works without written authorization from ShikshaSahayak is strictly prohibited.</li></ul>\n  <p><b>Reader Acknowledgement:</b> By accessing or using this publication, the reader acknowledges these terms and agrees to use the material ethically, responsibly, and for genuine learning.</p>\n</section>\n\n    \n<section class="pp-section">\n  <h2>About the Author</h2>\n  <div class="pp-author">\n    <div class="pp-avatar">AP</div>\n    <div>\n      <h3 style="margin-top:0">Ayush Pandey</h3>\n      <p><b>Engineer | Data Science learner | Student leader | Educational innovator</b></p>\n      <p>Ayush Pandey combines technical learning, competitive achievement, and student-community leadership through ShikshaSahayak, Electroverse Club, and academic initiatives.</p>\n      <p>Ayush Pandey is an aspiring Electrical Engineer, Data Science learner, student leader, and educational innovator, currently pursuing B.E. in Electrical Engineering at SSEC, Bhavnagar, along with B.S. in Data Science from IIT Madras. He completed his schooling from Air Force School Bamrauli, Prayagraj, where he developed a strong foundation in academics, discipline, leadership, and competitive excellence.</p>\n      <p>He is the Founder of Electroverse Club, a student-led technical club at SSEC, Bhavnagar, created with the vision of building a strong technical culture among engineering students through workshops, events, competitions, innovation-based learning, and peer-driven knowledge sharing. He is also the Founder of ShikshaSahayak, an educational website dedicated to providing accessible, structured, and student-friendly learning resources.</p>\n      <p>Ayush has demonstrated strong academic and competitive abilities by qualifying NDA Written Examination and SSB Interview, along with successfully qualifying JEE Main and JEE Advanced. His passion for knowledge and quick thinking has also earned him several achievements, including 1st Rank in Quiz at GTU Interzone, victories in multiple quiz competitions, and 1st Rank in the All-India Air Force Central Air Command Quiz Competition.</p>\n      <p>Beyond academics, he has also proven his excellence in communication and language skills by qualifying at the State Level in Spell Bee Competition. His leadership profile is further strengthened by his association as a Google Student Ambassador, upGrad Student Ambassador, and Microsoft Student Ambassador, reflecting his commitment to technology, learning, and community development.</p>\n      <p>With a strong blend of technical knowledge, leadership, competitive achievements, and educational vision, Ayush Pandey aims to contribute meaningfully to the student community by creating platforms, opportunities, and resources that help learners grow with confidence, clarity, and purpose.</p>\n    </div>\n  </div>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Subject Preparation Strategy</h2>\n  <ul><li>First complete <b>Units 1, 4, 5 and 6</b> because each has 20% syllabus weight and frequent 7-mark questions.</li><li>Prepare Unit 2 smartly: HIRA, fire classification, fire extinguishers, HAZOP/MSDS and Dow index basics.</li><li>Prepare Unit 3 through short notes: maintenance definition, functions, responsibilities, tools, cost and service life.</li><li>For every 7-mark answer, write definition, diagram/flow chart if possible, points, example and conclusion.</li><li>Make one-page sheets for formulas, wear/corrosion, fault tracing, maintenance procedures and Factories Act.</li></ul>\n  <h3>Tips To Score Full Marks In ISS GTU End Sem</h3>\n  <ul><li>Do not leave any sub-question blank. Even a correct definition with 3-4 points can fetch partial marks.</li><li>Use diagrams in fault tracing, decision tree, maintenance flow, lubrication and fire safety answers.</li><li>Write in GTU-friendly point format: heading, definition, numbered points, diagram, example, conclusion.</li><li>For 3 marks: definition plus 3 crisp points. For 4 marks: definition plus 4-5 points or a mini diagram. For 7 marks: full structure with 7-10 points.</li><li>Underline keywords such as unsafe act, unsafe condition, HIRA, preventive maintenance, repair cycle, severity rate and decision tree.</li><li>In procedure questions, show sequence. Marks are lost when steps are written randomly.</li></ul>\n  <h3>Paper Presentation And Writing Tips</h3>\n  <ul><li>Start every answer with a direct definition or one-line meaning.</li><li>Use clean margins, question numbers exactly as in paper, and leave one line between answers.</li><li>For repeated theory answers, write subheadings: Causes, Effects, Control, Advantages, Applications.</li><li>Use tables only for difference questions such as periodic vs preventive maintenance.</li><li>For Factories Act, mention exact facility/provision names: cleanliness, drinking water, lighting, guarding, pressure vessels, fire and welfare/safety provisions.</li><li>End 7-mark answers with a small conclusion or industrial example.</li></ul>\n  <h3>Paper Pattern Snapshot</h3>\n  <div class="pp-table-wrap"><table class="pp-table "><thead><tr><th>Item</th><th>Latest BE papers</th><th>Student action</th><th>Marks logic</th></tr></thead><tbody><tr><td>Q1</td><td>Compulsory 3 + 4 + 7</td><td>Prepare definitions plus one long answer from high-weight units</td><td>14</td></tr><tr><td>Q2-Q5</td><td>Each has OR choice</td><td>Prepare both likely topics per unit to avoid panic</td><td>56</td></tr><tr><td>Time</td><td>2.5 hours</td><td>Target about 18 minutes per 14-mark question</td><td>70</td></tr><tr><td>Best scoring form</td><td>Flow charts, steps, classification, definitions</td><td>Use diagrams wherever relevant</td><td>High</td></tr></tbody></table></div>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Repeated Trend Map</h2>\n  <div class="pp-note"><b>How to read this:</b> New-paper priority is given more importance than old-paper repetition. Older papers are used only where the same concept still exists in the latest syllabus.</div>\n  <div class="pp-table-wrap"><table class="pp-table "><thead><tr><th>Topic cluster</th><th>New BE papers</th><th>Old trend papers</th><th>Final priority</th></tr></thead><tbody><tr><td>Wear, corrosion and lubrication</td><td>Very frequent</td><td>Very frequent</td><td><span class="priority">A+</span></td></tr><tr><td>Fault tracing, decision tree and machine faults</td><td>Very frequent</td><td>Very frequent</td><td><span class="priority">A+</span></td></tr><tr><td>Periodic/preventive maintenance, overhauling, repair cycle</td><td>Very frequent</td><td>Very frequent</td><td><span class="priority">A+</span></td></tr><tr><td>Accidents, Factories Act, hazards and safety colour codes</td><td>Frequent</td><td>Very frequent</td><td><span class="priority">A</span></td></tr><tr><td>HIRA, fire classification, Dow index, HAZOP/MSDS</td><td>Frequent</td><td>Less in old papers</td><td><span class="priority">A-</span></td></tr><tr><td>Maintenance functions, tools, service life and cost</td><td>Frequent</td><td>Frequent</td><td><span class="priority">A-</span></td></tr><tr><td>Detailed replacement economy methods</td><td>Rare in new BE papers</td><td>Appears in old papers</td><td><span class="priority">B/C</span></td></tr></tbody></table></div>\n</section>\n\n    <section class="pp-section"><h2>Chapter Wise Most Important Topics And Questions</h2>\n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">20% | Very High</span>\n      <h3 style="margin-top:4px">Unit 1 - Industrial Safety</h3>\n      <p><b>Why it matters:</b> Appears in both latest BE papers and repeatedly in old papers; often asked as 7 marks.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Need for safety, safety and productivity</li><li>Accident: causes, types, results, control, injury, unsafe act, unsafe condition</li><li>Dangerous occurrence and reportable accidents</li><li>Theories of accident causation</li><li>Mechanical and electrical hazards with preventive steps</li><li>Factories Act 1948: health, safety, drinking water, cleanliness, lighting, fire, guarding, pressure vessels</li><li>Safety colour codes</li><li>Monitoring safety performance: frequency rate, severity rate, incidence rate, activity rate</li><li>Safety policy and safety standards</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>What is an accident? Explain causes, types and remedies/control measures.</li><li>Explain mechanical hazards and electrical hazards with preventive steps.</li><li>Write salient health and safety provisions of Factories Act, 1948.</li><li>Explain safety colour codes and their industrial use.</li><li>Define frequency rate, severity rate, incidence rate and activity rate.</li><li>Justify the need of safety policy and safety standards in an industry.</li></ol></div></div>\n    </div>\n    \n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">10% | High</span>\n      <h3 style="margin-top:4px">Unit 2 - Hazard Identification and Analysis</h3>\n      <p><b>Why it matters:</b> Lower syllabus weight, but the new papers ask HIRA, fire classification and fire/explosion rating directly.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Hazard and risk; types of hazards</li><li>Classification of fire and types of fire extinguishers</li><li>Fire, explosion and toxic gas release</li><li>Structure of HIRA</li><li>Inventory analysis</li><li>Dow Fire and Explosion Hazard Index</li><li>Preliminary hazard analysis</li><li>HAZOP methodology, criticality analysis, corrective action and follow-up</li><li>Chemical hazards, hazardous properties and MSDS</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>Describe the structure of hazard identification and risk assessment.</li><li>Define fire and explain classification of fire.</li><li>Explain types of hazards.</li><li>Explain Fire and Explosion Hazard Rating / Dow F&EI.</li><li>Write short notes on HAZOP, MSDS and chemical hazard control.</li></ol></div></div>\n    </div>\n    \n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">10% | High</span>\n      <h3 style="margin-top:4px">Unit 3 - Fundamentals of Maintenance Engineering</h3>\n      <p><b>Why it matters:</b> Asked frequently as maintenance department, tools, service life and types of maintenance.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Definition and aim of maintenance engineering</li><li>Primary and secondary functions of maintenance department</li><li>Responsibilities of maintenance department</li><li>Types of maintenance</li><li>Tools used for maintenance and their applications</li><li>Maintenance cost and replacement economy</li><li>Service life of equipment</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>Define maintenance and explain different types of maintenance.</li><li>Explain primary and secondary functions / responsibilities of maintenance department.</li><li>List types and applications of tools used for maintenance.</li><li>Explain maintenance cost and relation with replacement economy.</li><li>Write short note on service life of equipment.</li></ol></div></div>\n    </div>\n    \n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">20% | Very High</span>\n      <h3 style="margin-top:4px">Unit 4 - Wear, Lubrication and Corrosion</h3>\n      <p><b>Why it matters:</b> One of the safest scoring units; every recent paper has wear/corrosion/lubrication.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Wear: types, causes, effects and reduction methods</li><li>Specific wear types: adhesive, abrasive, corrosive, fatigue and molecular wear</li><li>Lubricants: types, role, functions and applications</li><li>Lubrication methods: splash, pressure grease gun, ring, oil bath and forced-feed methods</li><li>Corrosion definition, principle and factors affecting corrosion</li><li>Types of corrosion: uniform, galvanic, pitting, crevice, intergranular, stress corrosion</li><li>Corrosion prevention methods: material selection, design, coating, inhibitors, cathodic protection</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>Classify wear and explain any one type in detail.</li><li>List wear reduction methods and explain important methods.</li><li>Classify lubricants and explain their applications.</li><li>Explain methods of lubrication with neat sketches wherever possible.</li><li>Define corrosion and explain factors affecting corrosion.</li><li>Explain corrosion prevention methods.</li></ol></div></div>\n    </div>\n    \n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">20% | Very High</span>\n      <h3 style="margin-top:4px">Unit 5 - Fault Tracing</h3>\n      <p><b>Why it matters:</b> Extremely repeated; diagrams and flow charts make it high-scoring.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Fault tracing: concept, importance and features</li><li>Sequence / flow chart of fault-finding activities</li><li>Decision tree concept, steps, need and applications</li><li>Fault tree analysis basics</li><li>Decision tree for electric motor faults</li><li>Decision tree for air compressor or I.C. engine faults</li><li>Types of faults in machine tools and general causes</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>Define fault tracing and explain its importance.</li><li>Draw flow chart / sequence of fault-finding activities.</li><li>Explain decision tree concept and steps involved.</li><li>Draw decision tree to identify fault in electric motor.</li><li>Explain different types of faults in machine tools and causes.</li><li>Execute fault tree / fault analysis for electric motor or air compressor.</li></ol></div></div>\n    </div>\n    \n    <div class="pp-card" style="margin:16px 0">\n      <span class="tag">20% | Very High</span>\n      <h3 style="margin-top:4px">Unit 6 - Periodic and Preventive Maintenance</h3>\n      <p><b>Why it matters:</b> Latest papers strongly favor maintenance procedures, overhauling, repair cycle and preventive maintenance.</p>\n      <div class="pp-grid"><div><h4>Most important topics</h4><ul><li>Periodic inspection: concept, need and procedure</li><li>Degreasing, cleaning and repairing schemes</li><li>Overhauling of mechanical components</li><li>Overhauling of electrical motor</li><li>Common troubles and remedies of electric motor</li><li>Repair complexities and repair cycle</li><li>Preventive maintenance: definition, need, steps and advantages</li><li>Maintenance procedure for machine tools, pumps, air compressors and DG sets</li><li>Program and schedule of preventive maintenance</li></ul></div><div><h4>Most repeated / most probable questions</h4><ol><li>Differentiate periodic maintenance and preventive maintenance.</li><li>Explain steps/procedure for periodic and preventive maintenance of pumps.</li><li>Explain steps/procedure for air compressor / DG set / electrical motor.</li><li>Explain overhauling of electric motor and common troubles with remedies.</li><li>Write short note on repair cycle and its importance.</li><li>Explain degreasing methods and cleaning of machine parts.</li></ol></div></div>\n    </div>\n    </section>\n    \n<section class="pp-section">\n  <h2>Top 15 Combined Questions</h2>\n  <div class="pp-cards">\n    <div class="pp-card"><span class="tag">Priority A</span><h3>Must Prepare First</h3><ol><li>Accidents: causes, types, results, unsafe act/condition and control measures.</li><li>Factories Act 1948: salient health and safety provisions.</li><li>Wear: classification, causes, effects and wear reduction methods.</li><li>Corrosion: definition, types, factors and prevention methods.</li><li>Fault tracing: concept, importance, sequence and flow chart.</li></ol></div>\n    <div class="pp-card"><span class="tag">Priority B</span><h3>Very Likely</h3><ol><li>Decision tree: concept, steps and electric motor / air compressor fault example.</li><li>Periodic and preventive maintenance: definition, steps, advantages and difference.</li><li>Electrical motor overhauling: procedure, common troubles and remedies.</li><li>Mechanical/electrical hazards and preventive steps.</li><li>HIRA structure and fire classification / fire extinguishers.</li></ol></div>\n    <div class="pp-card"><span class="tag">Priority C</span><h3>Scoring Backup</h3><ol><li>Maintenance department: functions, responsibilities and tools.</li><li>Service life of equipment and maintenance cost with replacement economy.</li><li>Lubricants: types, functions, applications and lubrication methods.</li><li>Repair cycle, repair complexity, degreasing and cleaning methods.</li><li>Safety colour codes and safety performance rates.</li></ol></div>\n  </div>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Last Moment Skip List</h2>\n  <div class="pp-warning"><b>Disclaimer:</b> Skip only on your own risk. These topics are lower priority only when time is extremely limited. GTU can ask any syllabus topic.</div>\n  <ul><li>Deep numerical treatment of Dow Fire and Explosion Hazard Index, if only theory preparation is possible.</li><li>Detailed inventory analysis beyond definition, purpose and basic steps.</li><li>Very detailed HAZOP criticality follow-up formats; prepare basic HAZOP meaning and methodology at least.</li><li>Detailed replacement-economy methods such as MAPI/annual cost, because the latest BE ISS papers emphasize broader maintenance basics more.</li><li>Rare individual corrosion subtypes beyond pitting, galvanic and uniform corrosion.</li><li>Very uncommon machine-tool fault examples, after preparing electric motor, pump, air compressor and DG set.</li></ul>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Important Formulas, Theorems And Standard Points</h2>\n  <div class="pp-note"><b>Reference basis:</b> The latest syllabus specifically lists safety performance rates and refers to standard Industrial Safety and Maintenance Engineering books. Memorize the formulas with units and meaning.</div>\n  <div class="pp-table-wrap"><table class="pp-table pp-formula"><thead><tr><th>Formula / Concept</th><th>Expression</th><th>Use in answer</th></tr></thead><tbody><tr><td>Frequency Rate</td><td>\(\dfrac{\text{No. of disabling injuries}\times 10^{6}}{\text{Total man-hours worked}}\)</td><td>Accident frequency comparison</td></tr><tr><td>Severity Rate</td><td>\(\dfrac{\text{Man-days lost}\times 10^{6}}{\text{Total man-hours worked}}\)</td><td>Loss due to accident severity</td></tr><tr><td>Incidence Rate</td><td>\(\dfrac{\text{No. of reportable accidents}\times 1000}{\text{Average number of workers}}\)</td><td>Accidents per 1000 workers</td></tr><tr><td>Activity Rate</td><td>\(\dfrac{\text{Total accident cases}\times 10^{6}}{\text{Total man-hours worked}}\)</td><td>Overall safety activity trend</td></tr><tr><td>Risk</td><td>\(\text{Risk}=\text{Likelihood}\times\text{Severity}\)</td><td>HIRA ranking and control priority</td></tr><tr><td>Maintenance Cost</td><td>\(\text{Direct maintenance cost}+\text{downtime cost}+\text{indirect loss}\)</td><td>Replacement economy discussion</td></tr><tr><td>Availability</td><td>\(\dfrac{\text{Uptime}}{\text{Uptime}+\text{Downtime}}\)</td><td>Maintenance effectiveness</td></tr><tr><td>Service Life</td><td>Useful operating period before uneconomical operation</td><td>Equipment replacement and planning</td></tr></tbody></table></div>\n  <h3>Standard Theory Principles To Quote</h3>\n  <ul><li>Accident causation: accident usually occurs due to a chain of unsafe acts, unsafe conditions and management/control failure.</li><li>Hierarchy of control: eliminate, substitute, engineer control, administrative control and PPE.</li><li>Preventive maintenance principle: planned inspection and service reduces breakdown, downtime and repair cost.</li><li>Corrosion prevention principle: reduce electrochemical reaction by design, coating, inhibitors, cathodic protection or material selection.</li><li>Fault tracing principle: move from symptom to probable cause using logical checks, measurement and elimination.</li></ul>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Important Definitions And Derivations</h2>\n  <h3>Definitions</h3>\n  <div class="pp-table-wrap"><table class="pp-table "><thead><tr><th>Term</th><th>Exam-ready definition</th></tr></thead><tbody><tr><td>Industrial safety</td><td>Protection of workers, machines, materials and environment from accidents and hazards during industrial activity.</td></tr><tr><td>Accident</td><td>An unplanned event that causes injury, damage, loss or interruption of work.</td></tr><tr><td>Unsafe act</td><td>A human action that increases accident possibility, such as bypassing guards or ignoring PPE.</td></tr><tr><td>Unsafe condition</td><td>A physical workplace condition that may cause accident, such as exposed live wire or slippery floor.</td></tr><tr><td>Hazard</td><td>A source or situation with potential to cause harm.</td></tr><tr><td>Risk</td><td>Combination of probability and consequence of harm from a hazard.</td></tr><tr><td>Maintenance</td><td>Activities carried out to keep equipment in working condition or restore it after failure.</td></tr><tr><td>Wear</td><td>Progressive loss of material from a surface due to relative motion.</td></tr><tr><td>Corrosion</td><td>Deterioration of metal due to chemical or electrochemical reaction with environment.</td></tr><tr><td>Fault tracing</td><td>Systematic method of locating the cause of malfunction in equipment.</td></tr><tr><td>Preventive maintenance</td><td>Planned maintenance carried out before failure to prevent breakdown.</td></tr><tr><td>Periodic inspection</td><td>Regular checking of equipment condition at fixed intervals.</td></tr></tbody></table></div>\n  <h3>Must Prepare Derivation / Diagram-Type Answers</h3>\n  <ol><li>Define/use Frequency Rate, Severity Rate, Incidence Rate and Activity Rate with meaning.</li><li>Draw and explain fault-finding sequence flow chart.</li><li>Draw decision tree for electric motor becoming hot in short time.</li><li>Draw decision tree / analysis for air compressor or I.C. engine fault.</li><li>Explain HIRA structure as a stepwise diagram: identify hazard, assess risk, evaluate, control, review.</li><li>Explain preventive maintenance schedule as a flow: inspection, cleaning, lubrication, adjustment, repair, record.</li></ol>\n</section>\n\n    \n<section class="pp-section">\n  <h2>Last Minute Preparation Strategy</h2>\n  <div class="pp-grid">\n    <div class="pp-card"><span class="tag">If 3 Days Are Left</span><ul><li><b>Day 1:</b> Unit 1 and Unit 4. Prepare accidents, Factories Act, hazards, wear, corrosion and lubrication.</li><li><b>Day 2:</b> Unit 5 and Unit 6. Prepare fault tracing, decision tree, flow chart, preventive maintenance and overhauling.</li><li><b>Day 3:</b> Unit 2 and Unit 3 plus revision of top 15 questions and formulas.</li></ul></div>\n    <div class="pp-card"><span class="tag">If 1 Day Is Left</span><ul><li>Complete Priority A questions first.</li><li>Revise formulas and definitions.</li><li>Prepare one decision tree and one fault-finding flow chart perfectly.</li><li>Prepare one complete answer each for accident, Factories Act, corrosion, wear and preventive maintenance.</li><li>Read fire classification, HIRA and safety colour codes as short-answer backup.</li></ul></div>\n  </div>\n  <h3>Golden Rules</h3>\n  <ul><li>High-weight units first: 1, 4, 5 and 6.</li><li>Never study only old paper answers; align every answer with the latest syllabus keywords.</li><li>Diagrams convert average theory answers into high-scoring answers.</li><li>Write answers in points, not paragraphs.</li><li>Prepare definitions exactly; they are useful in 3-mark and opening lines of 7-mark answers.</li><li>Use industrial examples: electric motor, pump, air compressor, DG set, machine tool, boiler.</li></ul>\n  <h3>Sources Analysed</h3>\n  <ul><li>ISS Syllabus.pdf - GTU BE02R00061 Industrial Safety and Standards, latest syllabus.</li><li>new ISS Papers.pdf - BE Semester 2 ISS Summer 2025 and Winter 2025 papers.</li><li>ISS Papers.pdf - older Industrial Safety papers used only for trend repetition.</li><li>Reference books listed in the GTU syllabus: Maintenance Engineering Handbook; Maintenance Engineering by H. P. Garg; Industrial Safety, Health and Environment Management Systems by R. K. Jain; Safety Management references by Paul S. V., N. V. Krishnan, Grimaldi and Simonds.</li></ul>\n</section>\n\n    <footer class="pp-footer">\n      <div class="pp-links"><a href="https://shikshasahayak.org" target="_blank" rel="noopener noreferrer">Website</a><a href="https://www.instagram.com/padhaku_portal/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://chat.whatsapp.com/JKjcvjun6roIkbat7O59uJ" target="_blank" rel="noopener noreferrer">WA Community</a><a href="https://www.whatsapp.com/channel/0029VbCPjEsJf05VIeyIHv2i" target="_blank" rel="noopener noreferrer">WA Channel</a><a href="https://t.me/padhaku_portal" target="_blank" rel="noopener noreferrer">Telegram</a><a href="https://www.linkedin.com/company/padhakuportal/" target="_blank" rel="noopener noreferrer">LinkedIn</a></div>\n      <p class="pp-footnote">Copyright reserved by ShikshaSahayak. For student study use only.</p>\n    </footer>\n  </div>\n</div>\n<script>\nwindow.MathJax = {\n  tex: { inlineMath: [[''''\('''', ''''\)'''']], displayMath: [[''''\['''', ''''\]'''']], processEscapes: true, processEnvironments: true },\n  options: { skipHtmlTags: [''''script'''',''''noscript'''',''''style'''',''''textarea'''',''''pre'''',''''code''''] },\n  chtml: { scale: 1.03, mtextInheritFont: false }\n};\n</script>\n<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script>\n\n</body>\n</html>''',
  '\n',
  'char(10',
  NULL,
  NULL,
  'published',
  0,
  'datetime(''now'')',
  'datetime(''now'')'
