INSERT OR REPLACE INTO questions (id, quiz_id, question, options, correct_answer, explanation, created_at) VALUES (
  'Q_GTU_3130702_2024_012',
  'quiz_3130702_u1',
  'What is the minimum number of single-ended queues required to implement a Last-In, First-Out (LIFO) Stack?',
  '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]',
  1,
  'To simulate a Stack using Queues, 2 queues are required ($q_1$ and $q_2$). During push/pop, elements are dequeued and enqueued between queues to reverse the FIFO order to LIFO.',
  '2026-08-26 18:24:30'
);
INSERT OR REPLACE INTO questions (id, quiz_id, question, options, correct_answer, explanation, created_at) VALUES (
  'Q_GTU_3130702_2024_013',
  'quiz_3130702_u1',
  'What is the postfix evaluation result of the arithmetic expression: `6 3 2 + * 5 -`?',
  '[{"id":"A","text":"25"},{"id":"B","text":"30"},{"id":"C","text":"20"},{"id":"D","text":"15"}]',
  0,
  '1. Push 6, 3, 2. 2. Encounter `+`: pop 2, 3 $\rightarrow 3 + 2 = 5$, push 5. 3. Encounter `*`: pop 5, 6 $\rightarrow 6 \times 5 = 30$, push 30. 4. Push 5. 5. Encounter `-`: pop 5, 30 $\rightarrow 30 - 5 = 25$. Result $= 25$.',
  '2026-08-26 18:24:30'
);
